import { Request, Response, NextFunction } from 'express';
import { User } from './user.model';
import { NotFoundError, UnauthorizedError } from '../../utils/errors';

export const getProfile = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) {
      throw new UnauthorizedError('Authentication required');
    }

    const user = await User.findById(req.user.userId);
    if (!user) {
      throw new NotFoundError('User profile not found');
    }

    res.status(200).json({
      success: true,
      data: {
        id: user._id.toString(),
        name: user.name,
        email: user.email,
        role: user.role,
        profile: user.profile
      }
    });
  } catch (err) {
    next(err);
  }
};

export const updateProfile = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) {
      throw new UnauthorizedError('Authentication required');
    }

    const user = await User.findById(req.user.userId);
    if (!user) {
      throw new NotFoundError('User profile not found');
    }

    const { name, phone, headline, bio, skills, education, experience, projects, certifications } = req.body;

    if (name !== undefined) user.name = name;
    if (phone !== undefined) user.profile.phone = phone;
    if (headline !== undefined) user.profile.headline = headline;
    if (bio !== undefined) user.profile.bio = bio;
    if (skills !== undefined) user.profile.skills = skills;
    if (education !== undefined) user.profile.education = education;
    if (experience !== undefined) user.profile.experience = experience;
    if (projects !== undefined) user.profile.projects = projects;
    if (certifications !== undefined) user.profile.certifications = certifications;

    await user.save();

    res.status(200).json({
      success: true,
      message: 'Profile updated successfully',
      data: {
        id: user._id.toString(),
        name: user.name,
        email: user.email,
        role: user.role,
        profile: user.profile
      }
    });
  } catch (err) {
    next(err);
  }
};

