export interface ChatMessagePayload {
  role: 'user' | 'assistant' | 'system';
  content: string;
}

export interface ILLMProvider {
  name: string;
  generateResponse(messages: ChatMessagePayload[]): Promise<string>;
  generateStructuredResumeSection(sectionType: string, userInput: string, currentData?: unknown): Promise<any>;
}

class MockLLMProvider implements ILLMProvider {
  name = 'Mock LLM Provider (Development Fallback)';

  async generateResponse(messages: ChatMessagePayload[]): Promise<string> {
    const lastUserMsg = [...messages].reverse().find(m => m.role === 'user')?.content.toLowerCase() || '';
    logger.info(`[MockLLMProvider] Simulating career advice response for message: "${lastUserMsg.slice(0, 50)}..."`);

    if (lastUserMsg.includes('interview')) {
      return `Here are 4 targeted strategies for your upcoming interview:\n\n1. **STAR Technique**: Structure your stories with Situation, Task, Action, and Result.\n2. **Company Alignment**: Review their engineering principles and recent product launches.\n3. **System Design Practice**: Clearly articulate trade-offs between latency, consistency, and cost.\n4. **Questions for the Interviewer**: Ask about deployment cadence, team mentorship, and career progression frameworks.`;
    }

    if (lastUserMsg.includes('resume') || lastUserMsg.includes('cv')) {
      return `To make your resume stand out to hiring managers and ATS filters:\n\n- **Lead with Impact**: Use the formula "Accomplished [X], measured by [Y], by doing [Z]".\n- **Keyword Optimization**: Mirror the exact tools and methodologies from your target job descriptions.\n- **Clarity over Flash**: Use a structured single- or clean dual-column layout without unparsable graphics.\n- **Quantify Results**: Highlight metrics like "% latency reduction", "$ revenue uplift", or "hours saved per sprint".`;
    }

    if (lastUserMsg.includes('salary') || lastUserMsg.includes('offer')) {
      return `When approaching salary negotiations:\n\n1. Always benchmark market compensation across Levels.fyi, Glassdoor, and peer networks.\n2. Express enthusiasm for the team before discussing compensation adjustments.\n3. Frame your request around the quantifiable value you will deliver.\n4. Consider the total package, including equity vesting schedules, sign-on bonuses, and flexible work allowances.`;
    }

    return `Thank you for sharing your career goals! As your AI Career Coach, I can help you with:\n\n1. **Resume Refinement**: Polishing bullet points and optimizing for ATS.\n2. **Interview Preparation**: Behavioral questions, technical frameworks, and mock scenarios.\n3. **Career Trajectory & Transition**: Identifying high-leverage skills to bridge into your next role.\n4. **Negotiation Strategies**: Maximizing total compensation with confidence.\n\nWhat specific challenge would you like to tackle today?`;
  }

  async generateStructuredResumeSection(sectionType: string, userInput: string, currentData?: unknown): Promise<any> {
    logger.info(`[MockLLMProvider] Generating structured resume section for [${sectionType}]`);

    switch (sectionType) {
      case 'summary':
        return `Results-driven software engineering professional with proven expertise in building scalable cloud architectures and high-impact web applications. Adept at cross-functional leadership, modern full-stack frameworks, and delivering high-availability customer-facing products that drive measurable business outcomes.`;

      case 'experience':
        return [
          {
            id: 'mock-exp-1',
            company: 'Tech Innovators Inc.',
            role: 'Senior Full Stack Engineer',
            location: 'San Francisco, CA (Remote)',
            startDate: '2022-01',
            endDate: 'Present',
            current: true,
            description: 'Led end-to-end development of enterprise cloud services and micro-frontend architectures.',
            highlights: [
              'Architected distributed microservices handling over 5M daily requests with 99.99% availability.',
              'Spearheaded automated CI/CD pipeline modernization, reducing release lead time by 42%.',
              'Mentored 6 junior and mid-level engineers in test-driven development and clean code practices.'
            ]
          }
        ];

      case 'skills':
        return [
          'TypeScript', 'JavaScript', 'Node.js', 'React', 'Next.js', 'Express.js',
          'MongoDB', 'PostgreSQL', 'Docker', 'AWS', 'GraphQL', 'RESTful APIs',
          'Tailwind CSS', 'CI/CD Pipelines', 'System Design'
        ];

      case 'achievements':
        return [
          'Reduced API latency by 35% through Redis caching and query indexing.',
          'Awarded Engineering Excellence Award (Q3 2024) for zero-downtime database migration.',
          'Authored comprehensive team design system used across 8 distinct internal platforms.'
        ];

      default:
        return userInput;
    }
  }
}

class OpenAIProvider implements ILLMProvider {
  name = 'OpenAI Provider';
  private apiKey: string;
  private model: string;

  constructor(apiKey: string, model: string) {
    this.apiKey = apiKey;
    this.model = model;
  }

  async generateResponse(messages: ChatMessagePayload[]): Promise<string> {
    if (!this.apiKey) {
      logger.warn('OpenAI API key missing. Falling back to MockLLMProvider.');
      return new MockLLMProvider().generateResponse(messages);
    }

    try {
      const response = await fetch('https://api.openai.com/v1/chat/completions', {
        method: 'POST',
        headers: {
          'Content-Type': 'application/json',
          'Authorization': `Bearer ${this.apiKey}`
        },
        body: JSON.stringify({
          model: this.model || 'gpt-4o-mini',
          messages: [
            {
              role: 'system',
              content: 'You are an elite, encouraging, and highly analytical AI Career Coach and Resume Consultant.'
            },
            ...messages
          ],
          temperature: 0.7,
          max_tokens: 1000
        })
      });

      if (!response.ok) {
        const errorText = await response.text();
        logger.error(`OpenAI API error response: ${errorText}`);
        throw new Error(`OpenAI API returned status ${response.status}`);
      }

      const data = await response.json() as any;
      return data.choices[0]?.message?.content || 'No response generated';
    } catch (err) {
      logger.error('Failed to generate response with OpenAI, falling back to mock provider:', err);
      return new MockLLMProvider().generateResponse(messages);
    }
  }

  async generateStructuredResumeSection(sectionType: string, userInput: string, currentData?: unknown): Promise<any> {
    if (!this.apiKey) {
      return new MockLLMProvider().generateStructuredResumeSection(sectionType, userInput, currentData);
    }

    const prompt = `You are an expert resume writer. Generate polished, professional resume content for the "${sectionType}" section.
User input or guidance: "${userInput}"
Existing content: ${JSON.stringify(currentData || null)}
Return clean structured JSON matching the requested section content without markdown code blocks.`;

    try {
      const raw = await this.generateResponse([{ role: 'user', content: prompt }]);
      const cleaned = raw.replace(/```json/g, '').replace(/```/g, '').trim();
      return JSON.parse(cleaned);
    } catch {
      return new MockLLMProvider().generateStructuredResumeSection(sectionType, userInput, currentData);
    }
  }
}

export const getLLMProvider = (): ILLMProvider => {
  if (env.LLM_PROVIDER === 'openai' && env.LLM_API_KEY) {
    return new OpenAIProvider(env.LLM_API_KEY, env.LLM_MODEL);
  }
  return new MockLLMProvider();
};

