import { Request, Response, NextFunction } from 'express';
import { Types } from 'mongoose';
import { ChatSession, ChatMessage } from './chat.model';
import { getLLMProvider } from '../../integrations/llm';
import { NotFoundError, UnauthorizedError, ForbiddenError } from '../../utils/errors';

export const createSession = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { title } = req.body;

    const session = new ChatSession({
      userId: new Types.ObjectId(req.user.userId),
      title: title || 'New Career Conversation'
    });
    await session.save();

    res.status(201).json({
      success: true,
      data: { session }
    });
  } catch (err) {
    next(err);
  }
};

export const getSessions = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();

    const sessions = await ChatSession.find({ userId: req.user.userId })
      .sort({ updatedAt: -1 });

    res.status(200).json({
      success: true,
      data: { sessions }
    });
  } catch (err) {
    next(err);
  }
};

export const getSession = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { sessionId } = req.params;

    const session = await ChatSession.findById(sessionId);
    if (!session) {
      throw new NotFoundError('Chat session not found');
    }

    if (session.userId.toString() !== req.user.userId) {
      throw new ForbiddenError('You are not authorized to view this chat session');
    }

    const messages = await ChatMessage.find({ sessionId })
      .sort({ createdAt: 1 });

    res.status(200).json({
      success: true,
      data: {
        session,
        messages
      }
    });
  } catch (err) {
    next(err);
  }
};

export const updateSession = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { sessionId } = req.params;
    const { title } = req.body;

    const session = await ChatSession.findById(sessionId);
    if (!session) {
      throw new NotFoundError('Chat session not found');
    }

    if (session.userId.toString() !== req.user.userId) {
      throw new ForbiddenError('You are not authorized to modify this chat session');
    }

    session.title = title;
    await session.save();

    res.status(200).json({
      success: true,
      message: 'Chat session renamed',
      data: { session }
    });
  } catch (err) {
    next(err);
  }
};

export const deleteSession = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { sessionId } = req.params;

    const session = await ChatSession.findById(sessionId);
    if (!session) {
      throw new NotFoundError('Chat session not found');
    }

    if (session.userId.toString() !== req.user.userId) {
      throw new ForbiddenError('You are not authorized to delete this chat session');
    }

    await ChatMessage.deleteMany({ sessionId });
    await ChatSession.findByIdAndDelete(sessionId);

    res.status(200).json({
      success: true,
      message: 'Chat session deleted successfully'
    });
  } catch (err) {
    next(err);
  }
};

export const sendMessage = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { sessionId } = req.params;
    const { content } = req.body;

    const session = await ChatSession.findById(sessionId);
    if (!session) {
      throw new NotFoundError('Chat session not found');
    }

    if (session.userId.toString() !== req.user.userId) {
      throw new ForbiddenError('You are not authorized to participate in this chat session');
    }

    // 1. Save user message
    const userMessage = new ChatMessage({
      sessionId: session._id,
      userId: new Types.ObjectId(req.user.userId),
      role: 'user',
      content
    });
    await userMessage.save();

    // 2. Fetch recent history for context
    const recentMessages = await ChatMessage.find({ sessionId })
      .sort({ createdAt: -1 })
      .limit(10);
    recentMessages.reverse();

    const formattedHistory = recentMessages.map(m => ({
      role: m.role,
      content: m.content
    }));

    // 3. Call LLM provider
    const llmProvider = getLLMProvider();
    const aiResponseText = await llmProvider.generateResponse(formattedHistory);

    // 4. Save AI response
    const assistantMessage = new ChatMessage({
      sessionId: session._id,
      userId: new Types.ObjectId(req.user.userId),
      role: 'assistant',
      content: aiResponseText
    });
    await assistantMessage.save();

    // 5. Update session title if default
    if (session.title === 'New Career Conversation') {
      const generatedTitle = content.slice(0, 35) + (content.length > 35 ? '...' : '');
      session.title = generatedTitle;
    }
    session.updatedAt = new Date();
    await session.save();

    res.status(200).json({
      success: true,
      data: {
        userMessage,
        assistantMessage
      }
    });
  } catch (err) {
    next(err);
  }
};

import { Router } from 'express';
import {
  createSession,
  getSessions,
  getSession,
  updateSession,
  deleteSession,
  sendMessage
} from './chat.controller';
import { authenticate } from '../../middleware/auth';
import { validateRequest } from '../../middleware/validate';
import { createSessionSchema, updateSessionSchema, sendMessageSchema } from './chat.validation';

const router = Router();

router.use(authenticate);

router.post('/sessions', validateRequest({ body: createSessionSchema }), createSession);
router.get('/sessions', getSessions);
router.get('/sessions/:sessionId', getSession);
router.patch('/sessions/:sessionId', validateRequest({ body: updateSessionSchema }), updateSession);
router.delete('/sessions/:sessionId', deleteSession);
router.post('/sessions/:sessionId/messages', validateRequest({ body: sendMessageSchema }), sendMessage);

export default router;

