import { Request, Response, NextFunction } from 'express';
import { Types } from 'mongoose';
import { Resume, IResume } from './resume.model';
import { getLLMProvider } from '../../integrations/llm';
import { renderModernProfessional, renderATSClassic } from './resume.templates';
import { NotFoundError, UnauthorizedError, ForbiddenError } from '../../utils/errors';

export const createResume = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { title, template } = req.body;

    const resume = new Resume({
      userId: new Types.ObjectId(req.user.userId),
      title: title || 'Untitled Resume',
      template: template || 'MODERN_PROFESSIONAL'
    });
    await resume.save();

    res.status(201).json({
      success: true,
      data: { resume }
    });
  } catch (err) {
    next(err);
  }
};

export const getResumes = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();

    const resumes = await Resume.find({ userId: req.user.userId })
      .sort({ updatedAt: -1 });

    res.status(200).json({
      success: true,
      data: { resumes }
    });
  } catch (err) {
    next(err);
  }
};

export const getResume = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { id } = req.params;

    const resume = await Resume.findById(id);
    if (!resume) {
      throw new NotFoundError('Resume not found');
    }

    if (resume.userId.toString() !== req.user.userId) {
      throw new ForbiddenError('You do not have permission to view this resume');
    }

    res.status(200).json({
      success: true,
      data: { resume }
    });
  } catch (err) {
    next(err);
  }
};

export const updateResume = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { id } = req.params;

    const resume = await Resume.findById(id);
    if (!resume) {
      throw new NotFoundError('Resume not found');
    }

    if (resume.userId.toString() !== req.user.userId) {
      throw new ForbiddenError('You do not have permission to modify this resume');
    }

    const {
      title,
      template,
      personalInfo,
      summary,
      experience,
      education,
      skills,
      projects,
      certifications,
      achievements
    } = req.body;

    if (title !== undefined) resume.title = title;
    if (template !== undefined) resume.template = template;
    if (personalInfo !== undefined) resume.personalInfo = personalInfo;
    if (summary !== undefined) resume.summary = summary;
    if (experience !== undefined) resume.experience = experience;
    if (education !== undefined) resume.education = education;
    if (skills !== undefined) resume.skills = skills;
    if (projects !== undefined) resume.projects = projects;
    if (certifications !== undefined) resume.certifications = certifications;
    if (achievements !== undefined) resume.achievements = achievements;

    await resume.save();

    res.status(200).json({
      success: true,
      message: 'Resume updated successfully',
      data: { resume }
    });
  } catch (err) {
    next(err);
  }
};

export const deleteResume = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { id } = req.params;

    const resume = await Resume.findById(id);
    if (!resume) {
      throw new NotFoundError('Resume not found');
    }

    if (resume.userId.toString() !== req.user.userId) {
      throw new ForbiddenError('You do not have permission to delete this resume');
    }

    await Resume.findByIdAndDelete(id);

    res.status(200).json({
      success: true,
      message: 'Resume deleted successfully'
    });
  } catch (err) {
    next(err);
  }
};

export const generateSection = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { id } = req.params;
    const { section, prompt } = req.body;

    const resume = await Resume.findById(id);
    if (!resume) {
      throw new NotFoundError('Resume not found');
    }

    if (resume.userId.toString() !== req.user.userId) {
      throw new ForbiddenError('You do not have permission to modify this resume');
    }

    const llmProvider = getLLMProvider();
    const currentData = (resume as any)[section];
    const generatedContent = await llmProvider.generateStructuredResumeSection(section, prompt, currentData);

    (resume as any)[section] = generatedContent;
    await resume.save();

    res.status(200).json({
      success: true,
      message: `Section ${section} generated successfully`,
      data: {
        section,
        content: generatedContent,
        resume
      }
    });
  } catch (err) {
    next(err);
  }
};

export const exportResume = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { id } = req.params;
    const templateOverride = req.query.template as string | undefined;

    const resume = await Resume.findById(id);
    if (!resume) {
      throw new NotFoundError('Resume not found');
    }

    if (resume.userId.toString() !== req.user.userId) {
      throw new ForbiddenError('You do not have permission to export this resume');
    }

    const selectedTemplate = templateOverride || resume.template || 'MODERN_PROFESSIONAL';
    const html = selectedTemplate === 'ATS_CLASSIC'
      ? renderATSClassic(resume)
      : renderModernProfessional(resume);

    if (req.query.format === 'raw') {
      res.setHeader('Content-Type', 'text/html');
      res.send(html);
      return;
    }

    res.status(200).json({
      success: true,
      data: {
        template: selectedTemplate,
        html
      }
    });
  } catch (err) {
    next(err);
  }
};

