import mongoose, { Document, Schema, Types } from 'mongoose';

export interface IAvailabilitySlot {
  dayOfWeek: number; // 0 = Sunday, 1 = Monday, ..., 6 = Saturday
  startTime: string; // "09:00"
  endTime: string;   // "17:00"
}

export interface IConsultant extends Document {
  _id: Types.ObjectId;
  name: string;
  title: string;
  bio: string;
  expertise: string[];
  email: string;
  hourlyRate: number; // in cents
  durationMinutes: number;
  isActive: boolean;
  avatarUrl?: string;
  availability: IAvailabilitySlot[];
  createdAt: Date;
  updatedAt: Date;
}

const AvailabilitySlotSchema = new Schema<IAvailabilitySlot>({
  dayOfWeek: { type: Number, required: true, min: 0, max: 6 },
  startTime: { type: String, required: true },
  endTime: { type: String, required: true }
}, { _id: false });

const ConsultantSchema = new Schema<IConsultant>({
  name: { type: String, required: true, trim: true },
  title: { type: String, required: true, trim: true },
  bio: { type: String, required: true },
  expertise: { type: [String], default: [] },
  email: { type: String, required: true, lowercase: true, trim: true },
  hourlyRate: { type: Number, required: true, default: 12000 }, // $120.00
  durationMinutes: { type: Number, required: true, default: 45 },
  isActive: { type: Boolean, default: true, index: true },
  avatarUrl: { type: String, default: '' },
  availability: {
    type: [AvailabilitySlotSchema],
    default: () => [
      { dayOfWeek: 1, startTime: '09:00', endTime: '17:00' },
      { dayOfWeek: 2, startTime: '09:00', endTime: '17:00' },
      { dayOfWeek: 3, startTime: '09:00', endTime: '17:00' },
      { dayOfWeek: 4, startTime: '09:00', endTime: '17:00' },
      { dayOfWeek: 5, startTime: '09:00', endTime: '17:00' }
    ]
  }
}, {
  timestamps: true
});

ConsultantSchema.index({ expertise: 1 });

export const Consultant = mongoose.model<IConsultant>('Consultant', ConsultantSchema);

