export const getConsultants = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    const { expertise, search } = req.query;
    const filter: Record<string, any> = { isActive: true };

    if (expertise) {
      filter.expertise = { $in: [String(expertise)] };
    }

    if (search) {
      filter.$or = [
        { name: { $regex: String(search), $options: 'i' } },
        { title: { $regex: String(search), $options: 'i' } },
        { bio: { $regex: String(search), $options: 'i' } }
      ];
    }

    const consultants = await Consultant.find(filter).sort({ name: 1 });

    res.status(200).json({
      success: true,
      data: { consultants }
    });
  } catch (err) {
    next(err);
  }
};

