export const getConsultantAvailability = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    const { id } = req.params;
    const { date } = req.query; // Expects YYYY-MM-DD

    if (!date || typeof date !== 'string') {
      throw new BadRequestError('Query parameter "date" (YYYY-MM-DD) is required');
    }

    const consultant = await Consultant.findById(id);
    if (!consultant) {
      throw new NotFoundError('Consultant not found');
    }

    // Parse target date
    const targetDate = new Date(`${date}T00:00:00.000Z`);
    if (isNaN(targetDate.getTime())) {
      throw new BadRequestError('Invalid date format. Use YYYY-MM-DD.');
    }

    const dayOfWeek = targetDate.getUTCDay();
    const dayConfig = consultant.availability.find(a => a.dayOfWeek === dayOfWeek);

    if (!dayConfig) {
      res.status(200).json({
        success: true,
        data: {
          date,
          dayOfWeek,
          slots: []
        }
      });
      return;
    }

    // Fetch existing active bookings for this consultant on this day
    const startOfDay = new Date(`${date}T00:00:00.000Z`);
    const endOfDay = new Date(`${date}T23:59:59.999Z`);

    const existingBookings = await Booking.find({
      consultantId: consultant._id,
      status: { $in: ['PENDING_PAYMENT', 'PAID', 'CONFIRMED'] },
      startTime: { $gte: startOfDay, $lte: endOfDay }
    });

    const bookedStarts = new Set(
      existingBookings.map(b => b.startTime.toISOString())
    );

    // Generate potential slots based on duration
    const duration = consultant.durationMinutes || 45;
    const [startHour, startMin] = dayConfig.startTime.split(':').map(Number);
    const [endHour, endMin] = dayConfig.endTime.split(':').map(Number);

    const startTotalMins = startHour * 60 + startMin;
    const endTotalMins = endHour * 60 + endMin;

    const slots: { startTime: string; endTime: string; isAvailable: boolean }[] = [];
    const now = new Date();

    for (let m = startTotalMins; m + duration <= endTotalMins; m += duration) {
      const slotHour = Math.floor(m / 60);
      const slotMin = m % 60;
      const endM = m + duration;
      const endSlotHour = Math.floor(endM / 60);
      const endSlotMin = endM % 60;

      const slotStartIso = new Date(
        Date.UTC(
          targetDate.getUTCFullYear(),
          targetDate.getUTCMonth(),
          targetDate.getUTCDate(),
          slotHour,
          slotMin,
          0
        )
      ).toISOString();

      const slotEndIso = new Date(
        Date.UTC(
          targetDate.getUTCFullYear(),
          targetDate.getUTCMonth(),
          targetDate.getUTCDate(),
          endSlotHour,
          endSlotMin,
          0
        )
      ).toISOString();

      const isPast = new Date(slotStartIso).getTime() <= now.getTime();
      const isBooked = bookedStarts.has(slotStartIso);

      slots.push({
        startTime: slotStartIso,
        endTime: slotEndIso,
        isAvailable: !isPast && !isBooked
      });
    }

    res.status(200).json({
      success: true,
      data: {
        date,
        dayOfWeek,
        durationMinutes: duration,
        slots
      }
    });
  } catch (err) {
    next(err);
  }
};

