export type BookingStatus =
  | 'PENDING_PAYMENT'
  | 'PAYMENT_FAILED'
  | 'PAID'
  | 'CONFIRMED'
  | 'CANCELLED'
  | 'COMPLETED';

export type CalendarSyncStatus = 'NOT_SCHEDULED' | 'SCHEDULED' | 'FAILED';
export type EmailSyncStatus = 'NOT_SENT' | 'SENT' | 'FAILED';

export interface IBooking extends Document {
  _id: Types.ObjectId;
  userId: Types.ObjectId;
  consultantId: Types.ObjectId;
  userName: string;
  userEmail: string;
  userPhone?: string;
  agenda: string;
  startTime: Date;
  endTime: Date;
  durationMinutes: number;
  amount: number; // in cents
  currency: string;
  status: BookingStatus;
  calendarEventId?: string;
  meetingUrl?: string;
  calendarStatus: CalendarSyncStatus;
  emailStatus: EmailSyncStatus;
  createdAt: Date;
  updatedAt: Date;
}

const BookingSchema = new Schema<IBooking>({
  userId: { type: Schema.Types.ObjectId, ref: 'User', required: true, index: true },
  consultantId: { type: Schema.Types.ObjectId, ref: 'Consultant', required: true, index: true },
  userName: { type: String, required: true, trim: true },
  userEmail: { type: String, required: true, lowercase: true, trim: true },
  userPhone: { type: String, default: '' },
  agenda: { type: String, required: true },
  startTime: { type: Date, required: true, index: true },
  endTime: { type: Date, required: true },
  durationMinutes: { type: Number, required: true, default: 45 },
  amount: { type: Number, required: true },
  currency: { type: String, default: 'usd', lowercase: true },
  status: {
    type: String,
    enum: ['PENDING_PAYMENT', 'PAYMENT_FAILED', 'PAID', 'CONFIRMED', 'CANCELLED', 'COMPLETED'],
    default: 'PENDING_PAYMENT',
    index: true
  },
  calendarEventId: { type: String },
  meetingUrl: { type: String },
  calendarStatus: {
    type: String,
    enum: ['NOT_SCHEDULED', 'SCHEDULED', 'FAILED'],
    default: 'NOT_SCHEDULED'
  },
  emailStatus: {
    type: String,
    enum: ['NOT_SENT', 'SENT', 'FAILED'],
    default: 'NOT_SENT'
  }
}, {
  timestamps: true
});

// Indexes for conflict prevention and rapid lookup
BookingSchema.index({ consultantId: 1, startTime: 1, status: 1 });
BookingSchema.index({ userId: 1, createdAt: -1 });

export const Booking = mongoose.model<IBooking>('Booking', BookingSchema);

