import { Request, Response, NextFunction } from 'express';
import { Types } from 'mongoose';
import { Booking, BookingStatus } from './booking.model';
import { Consultant } from '../consultants/consultant.model';
import { BadRequestError, NotFoundError, UnauthorizedError, ForbiddenError, ConflictError } from '../../utils/errors';

export const createBooking = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { consultantId, startTime, userName, userEmail, userPhone, agenda } = req.body;

    const startDate = new Date(startTime);
    const now = new Date();

    // 1. Reject bookings in the past
    if (startDate.getTime() <= now.getTime()) {
      throw new BadRequestError('Cannot book consultation appointments in the past');
    }

    // 2. Validate consultant exists and is active
    const consultant = await Consultant.findById(consultantId);
    if (!consultant || !consultant.isActive) {
      throw new NotFoundError('Selected consultant is not available for bookings');
    }

    const duration = consultant.durationMinutes || 45;
    const endDate = new Date(startDate.getTime() + duration * 60 * 1000);

    // 3. Concurrency / Overlap check
    // Check if consultant has an active overlapping booking
    const overlapping = await Booking.findOne({
      consultantId: consultant._id,
      status: { $in: ['PENDING_PAYMENT', 'PAID', 'CONFIRMED'] },
      $or: [
        {
          startTime: { $lt: endDate },
          endTime: { $gt: startDate }
        }
      ]
    });

    if (overlapping) {
      throw new ConflictError('This time slot has already been reserved. Please choose another time.');
    }

    // 4. Create booking with server-calculated price
    const booking = new Booking({
      userId: new Types.ObjectId(req.user.userId),
      consultantId: consultant._id,
      userName,
      userEmail,
      userPhone: userPhone || '',
      agenda,
      startTime: startDate,
      endTime: endDate,
      durationMinutes: duration,
      amount: consultant.hourlyRate, // Strict server-side pricing
      currency: 'usd',
      status: 'PENDING_PAYMENT',
      calendarStatus: 'NOT_SCHEDULED',
      emailStatus: 'NOT_SENT'
    });

    await booking.save();

    res.status(201).json({
      success: true,
      message: 'Consultation slot reserved successfully. Please complete payment to confirm.',
      data: { booking }
    });
  } catch (err) {
    next(err);
  }
};

export const getBookings = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();

    const page = Math.max(1, parseInt(String(req.query.page || 1), 10));
    const limit = Math.min(100, Math.max(1, parseInt(String(req.query.limit || 10), 10)));
    const status = req.query.status as BookingStatus | undefined;
    const search = req.query.search as string | undefined;
    const sortField = String(req.query.sort || '-createdAt');

    // Scoped filter to current user
    const filter: Record<string, any> = { userId: new Types.ObjectId(req.user.userId) };

    if (status) {
      filter.status = status;
    }

    if (search) {
      filter.$or = [
        { userName: { $regex: search, $options: 'i' } },
        { userEmail: { $regex: search, $options: 'i' } },
        { agenda: { $regex: search, $options: 'i' } }
      ];
    }

    // Allowed sort whitelist
    const allowedSorts = ['createdAt', '-createdAt', 'startTime', '-startTime', 'amount', '-amount'];
    const sort = allowedSorts.includes(sortField) ? sortField : '-createdAt';

    const total = await Booking.countDocuments(filter);
    const totalPages = Math.ceil(total / limit);
    const skip = (page - 1) * limit;

    const data = await Booking.find(filter)
      .populate('consultantId', 'name title email avatarUrl')
      .sort(sort)
      .skip(skip)
      .limit(limit);

    res.status(200).json({
      success: true,
      data,
      pagination: {
        page,
        limit,
        total,
        totalPages
      }
    });
  } catch (err) {
    next(err);
  }
};

export const getBookingById = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { id } = req.params;

    const booking = await Booking.findById(id).populate('consultantId', 'name title email avatarUrl hourlyRate');
    if (!booking) {
      throw new NotFoundError('Booking record not found');
    }

    if (booking.userId.toString() !== req.user.userId && req.user.role !== 'ADMIN') {
      throw new ForbiddenError('You do not have access to view this booking');
    }

    res.status(200).json({
      success: true,
      data: { booking }
    });
  } catch (err) {
    next(err);
  }
};

export const cancelBooking = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { id } = req.params;

    const booking = await Booking.findById(id);
    if (!booking) {
      throw new NotFoundError('Booking record not found');
    }

    if (booking.userId.toString() !== req.user.userId && req.user.role !== 'ADMIN') {
      throw new ForbiddenError('You do not have access to cancel this booking');
    }

    // State machine check
    const nonCancellableStates: BookingStatus[] = ['CANCELLED', 'COMPLETED', 'PAYMENT_FAILED'];
    if (nonCancellableStates.includes(booking.status)) {
      throw new BadRequestError(`Cannot cancel a booking in status "${booking.status}"`);
    }

    booking.status = 'CANCELLED';
    await booking.save();

    res.status(200).json({
      success: true,
      message: 'Booking cancelled successfully',
      data: { booking }
    });
  } catch (err) {
    next(err);
  }
};

