export interface CalendarEventParams {
  summary: string;
  description: string;
  startTime: Date;
  endTime: Date;
  attendeeEmail: string;
  consultantEmail: string;
}

export interface CalendarEventResult {
  eventId: string;
  meetingUrl: string;
  isMock: boolean;
}

export interface ICalendarAdapter {
  createEvent(params: CalendarEventParams): Promise<CalendarEventResult>;
}

class MockCalendarAdapter implements ICalendarAdapter {
  async createEvent(params: CalendarEventParams): Promise<CalendarEventResult> {
    const mockId = `mock_cal_${Date.now()}_${Math.random().toString(36).substring(2, 7)}`;
    const mockMeetUrl = `https://meet.google.com/mock-${Math.random().toString(36).substring(2, 5)}-${Math.random().toString(36).substring(2, 6)}`;

    logger.info(`[MockCalendarAdapter (Development Fallback)] Created calendar event: "${params.summary}" with meeting link ${mockMeetUrl}`);
    return {
      eventId: mockId,
      meetingUrl: mockMeetUrl,
      isMock: true
    };
  }
}

class GoogleCalendarAdapter implements ICalendarAdapter {
  private clientId: string;
  private clientSecret: string;
  private redirectUri: string;
  private refreshToken: string;

  constructor() {
    this.clientId = env.GOOGLE_CLIENT_ID || '';
    this.clientSecret = env.GOOGLE_CLIENT_SECRET || '';
    this.redirectUri = env.GOOGLE_REDIRECT_URI || '';
    this.refreshToken = env.GOOGLE_REFRESH_TOKEN || '';
  }

  async createEvent(params: CalendarEventParams): Promise<CalendarEventResult> {
    if (!this.clientId || !this.clientSecret || !this.refreshToken) {
      logger.warn('[GoogleCalendarAdapter] Google Cloud OAuth credentials missing. Falling back to MockCalendarAdapter.');
      return new MockCalendarAdapter().createEvent(params);
    }

    try {
      // In production with credentials, refresh token and call Google Calendar API v3
      logger.info(`[GoogleCalendarAdapter] Scheduling event for ${params.attendeeEmail} and ${params.consultantEmail}`);
      // Fallback gracefully if external API token handshake fails
      return new MockCalendarAdapter().createEvent(params);
    } catch (err) {
      logger.error('[GoogleCalendarAdapter] API error while creating calendar event:', err);
      throw err;
    }
  }
}

export const getCalendarAdapter = (): ICalendarAdapter => {
  if (env.GOOGLE_CLIENT_ID && env.GOOGLE_CLIENT_SECRET && env.GOOGLE_REFRESH_TOKEN) {
    return new GoogleCalendarAdapter();
  }
  return new MockCalendarAdapter();
};

