    logger.info(`[MockEmailAdapter (Development Fallback)] Booking confirmation email dispatched to ${params.to} for Booking ID: ${params.bookingId}`);
    logger.info(`[MockEmailAdapter] Meeting details: Consultant: ${params.consultantName}, Date: ${params.dateStr} at ${params.timeStr}, Link: ${params.meetingUrl || 'Pending'}`);
