class NodemailerAdapter implements IEmailAdapter {
  private transporter: nodemailer.Transporter | null = null;

  constructor() {
    if (env.EMAIL_USER && env.EMAIL_PASSWORD) {
      this.transporter = nodemailer.createTransport({
        host: env.EMAIL_HOST,
        port: env.EMAIL_PORT,
        secure: env.EMAIL_PORT === 465,
        auth: {
          user: env.EMAIL_USER,
          pass: env.EMAIL_PASSWORD
        }
      });
    }
  }

  async sendBookingConfirmation(params: BookingConfirmationEmailParams): Promise<boolean> {
    if (!this.transporter) {
      logger.warn('[NodemailerAdapter] SMTP credentials not configured. Falling back to MockEmailAdapter.');
      return new MockEmailAdapter().sendBookingConfirmation(params);
    }

    try {
      const html = `
        <div style="font-family: Arial, sans-serif; max-width: 600px; margin: 0 auto; padding: 20px; border: 1px solid #e2e8f0; border-radius: 8px;">
          <h2 style="color: #2563eb; margin-top: 0;">Consultation Booking Confirmed!</h2>
