          <p>Your career consultation with <strong>${params.consultantName}</strong> has been successfully booked and confirmed.</p>

          <div style="background-color: #f8fafc; padding: 16px; border-radius: 6px; margin: 20px 0;">
            <p style="margin: 4px 0;"><strong>Date:</strong> ${params.dateStr}</p>
            <p style="margin: 4px 0;"><strong>Time:</strong> ${params.timeStr} (UTC)</p>
            <p style="margin: 4px 0;"><strong>Booking Reference:</strong> <code>${params.bookingId}</code></p>
            <p style="margin: 4px 0;"><strong>Agenda:</strong> ${params.agenda}</p>
            ${params.meetingUrl ? `<p style="margin: 12px 0 4px 0;"><strong>Meeting Link:</strong> <a href="${params.meetingUrl}" style="color: #2563eb; font-weight: bold;">Join Video Consultation</a></p>` : ''}
          </div>

          <p style="color: #64748b; font-size: 13px;">If you have any questions or need to reschedule, please reach out through your dashboard.</p>
        </div>
      `;

      await this.transporter.sendMail({
        from: env.EMAIL_FROM,
        to: params.to,
        subject: `Confirmed: Consultation with ${params.consultantName}`,
        html
      });

      logger.info(`[NodemailerAdapter] Confirmation email successfully delivered to ${params.to}`);
      return true;
    } catch (err) {
      logger.error('[NodemailerAdapter] Error sending confirmation email:', err);
      throw err;
    }
  }
}

export const getEmailAdapter = (): IEmailAdapter => {
  if (env.EMAIL_USER && env.EMAIL_PASSWORD) {
    return new NodemailerAdapter();
  }
  return new MockEmailAdapter();
};

