export const createCheckoutSession = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const { bookingId } = req.body;

    if (!bookingId) {
      throw new BadRequestError('bookingId is required');
    }

    const booking = await Booking.findById(bookingId).populate('consultantId');
    if (!booking) {
      throw new NotFoundError('Booking record not found');
    }

    if (booking.userId.toString() !== req.user.userId) {
      throw new ForbiddenError('You do not have permission to pay for this booking');
    }

    if (booking.status !== 'PENDING_PAYMENT') {
      throw new BadRequestError(`Cannot initiate payment for booking in "${booking.status}" status`);
    }

    const consultant = booking.consultantId as any;
    const consultantName = consultant?.name || 'Career Consultant';

    let checkoutUrl = '';
    let sessionId = '';

    if (stripeClient) {
      // Real Stripe Checkout Session
      const session = await stripeClient.checkout.sessions.create({
        payment_method_types: ['card'],
        line_items: [
          {
            price_data: {
              currency: booking.currency || 'usd',
              product_data: {
                name: `Consultation with ${consultantName}`,
                description: `45-min Career Coaching & Advisory (${booking.agenda.slice(0, 80)})`
              },
              unit_amount: booking.amount // Strictly backend calculated
            },
            quantity: 1
          }
        ],
        mode: 'payment',
        success_url: `${env.FRONTEND_URL}/payment/success?session_id={CHECKOUT_SESSION_ID}`,
        cancel_url: `${env.FRONTEND_URL}/payment/cancel?booking_id=${booking._id}`,
        client_reference_id: booking._id.toString(),
        metadata: {
          bookingId: booking._id.toString(),
          userId: req.user.userId
        }
      });

      sessionId = session.id;
      checkoutUrl = session.url || '';
    } else {
      // Local development fallback session
      sessionId = `cs_test_mock_${booking._id}_${Date.now()}`;
      checkoutUrl = `${env.FRONTEND_URL}/payment/success?session_id=${sessionId}`;
      logger.info(`[MockStripe (Dev Fallback)] Generated mock checkout session ${sessionId}`);
    }

    // Persist Payment document
    await Payment.findOneAndUpdate(
      { bookingId: booking._id },
      {
        bookingId: booking._id,
        userId: new Types.ObjectId(req.user.userId),
        stripeSessionId: sessionId,
        amount: booking.amount,
        currency: booking.currency || 'usd',
        status: 'PENDING'
      },
      { upsert: true, new: true }
    );

    res.status(200).json({
      success: true,
      data: {
        sessionId,
        checkoutUrl
      }
    });
  } catch (err) {
    next(err);
  }
};

export const handleWebhook = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    const sig = req.headers['stripe-signature'] as string;
    let event: Stripe.Event;

    if (stripeClient && env.STRIPE_WEBHOOK_SECRET && !env.STRIPE_WEBHOOK_SECRET.includes('placeholder')) {
      if (!sig) {
        throw new BadRequestError('Missing stripe-signature header');
      }
      try {
        event = stripeClient.webhooks.constructEvent(req.body, sig, env.STRIPE_WEBHOOK_SECRET);
      } catch (err: any) {
        logger.error(`Webhook signature verification failed: ${err.message}`);
        res.status(400).send(`Webhook Error: ${err.message}`);
        return;
      }
    } else {
      // Development mock webhook simulation or test runner payload
      event = typeof req.body === 'string' ? JSON.parse(req.body) : req.body;
      logger.info(`[PaymentWebhook] Processing event in dev/test mode: ${event?.type}`);
    }

    if (!event || !event.type) {
      throw new BadRequestError('Invalid webhook event payload');
    }

    const eventId = event.id || `evt_${Date.now()}`;

    if (event.type === 'checkout.session.completed') {
      const session = event.data.object as Stripe.Checkout.Session;
      const sessionId = session.id;
      const bookingId = session.metadata?.bookingId || session.client_reference_id;

      // Locate payment record
      let payment = await Payment.findOne({
        $or: [{ stripeSessionId: sessionId }, { bookingId: bookingId ? new Types.ObjectId(bookingId) : undefined }]
      });

      if (!payment && bookingId) {
        // Fallback create if not initialized
        const booking = await Booking.findById(bookingId);
        if (booking) {
          payment = new Payment({
            bookingId: booking._id,
            userId: booking.userId,
            stripeSessionId: sessionId,
            amount: booking.amount,
            status: 'PENDING'
          });
          await payment.save();
        }
      }

      if (!payment) {
        logger.warn(`[PaymentWebhook] Payment record not found for session ${sessionId}`);
        res.status(200).json({ received: true, note: 'Payment record not found' });
        return;
      }

      // STRICT IDEMPOTENCY CHECK
      if (payment.processedWebhookEvents.includes(eventId)) {
        logger.info(`[PaymentWebhook] Idempotent skip: Event ${eventId} was already processed for payment ${payment._id}`);
        res.status(200).json({ received: true, duplicate: true });
        return;
      }

      // Mark payment as succeeded
      payment.status = 'SUCCEEDED';
      if (session.payment_intent) {
        payment.stripePaymentIntentId = String(session.payment_intent);
      }
      payment.processedWebhookEvents.push(eventId);
      await payment.save();

      // Transition booking state to CONFIRMED
      const booking = await Booking.findById(payment.bookingId).populate('consultantId');
      if (booking) {
        booking.status = 'CONFIRMED';

        const consultant = booking.consultantId as any;
        const consultantEmail = consultant?.email || 'consultant@careerplatform.com';
        const consultantName = consultant?.name || 'Career Consultant';

        // Trigger Google Calendar integration
        try {
          const calendarAdapter = getCalendarAdapter();
          const calResult = await calendarAdapter.createEvent({
            summary: `Career Consultation: ${booking.userName} & ${consultantName}`,
            description: `Agenda: ${booking.agenda}`,
            startTime: booking.startTime,
            endTime: booking.endTime,
            attendeeEmail: booking.userEmail,
            consultantEmail
          });

          booking.calendarEventId = calResult.eventId;
          booking.meetingUrl = calResult.meetingUrl;
          booking.calendarStatus = 'SCHEDULED';
        } catch (calErr) {
          logger.error('[PaymentWebhook] Google Calendar creation failed, preserving confirmed payment:', calErr);
          booking.calendarStatus = 'FAILED';
        }

        // Trigger Email Notification integration
        try {
          const emailAdapter = getEmailAdapter();
          await emailAdapter.sendBookingConfirmation({
            to: booking.userEmail,
            userName: booking.userName,
            consultantName,
            dateStr: booking.startTime.toISOString().split('T')[0],
            timeStr: booking.startTime.toISOString().split('T')[1].slice(0, 5),
            meetingUrl: booking.meetingUrl,
            bookingId: booking._id.toString(),
            agenda: booking.agenda
          });

          booking.emailStatus = 'SENT';
        } catch (emailErr) {
          logger.error('[PaymentWebhook] Confirmation email delivery failed, preserving confirmed payment:', emailErr);
          booking.emailStatus = 'FAILED';
        }

        await booking.save();
        logger.info(`[PaymentWebhook] Booking ${booking._id} transitioned to CONFIRMED`);
      }
    } else if (event.type === 'payment_intent.payment_failed') {
      const paymentIntent = event.data.object as Stripe.PaymentIntent;
      const payment = await Payment.findOne({ stripePaymentIntentId: paymentIntent.id });
      if (payment) {
        payment.status = 'FAILED';
        payment.processedWebhookEvents.push(eventId);
        await payment.save();

        await Booking.findByIdAndUpdate(payment.bookingId, { status: 'PAYMENT_FAILED' });
      }
    }

    res.status(200).json({ received: true });
  } catch (err) {
    next(err);
  }
};

export const getPaymentStatus = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    const { bookingId } = req.params;
    const { sessionId } = req.query;

    let payment;
    if (bookingId && bookingId !== 'undefined') {
      payment = await Payment.findOne({ bookingId: new Types.ObjectId(bookingId) });
    } else if (sessionId) {
      payment = await Payment.findOne({ stripeSessionId: String(sessionId) });
    }

    if (!payment) {
      throw new NotFoundError('Payment information not found');
    }

    const booking = await Booking.findById(payment.bookingId).populate('consultantId', 'name title email avatarUrl');

    res.status(200).json({
      success: true,
      data: {
        paymentStatus: payment.status,
        amount: payment.amount,
        currency: payment.currency,
        booking
      }
    });
  } catch (err) {
    next(err);
  }
};

