export const getDashboardMetrics = async (req: Request, res: Response, next: NextFunction): Promise<void> => {
  try {
    if (!req.user) throw new UnauthorizedError();
    const userObjectId = new Types.ObjectId(req.user.userId);
    const now = new Date();

    // Run parallel aggregation queries scoped to this authenticated user
    const [
      totalResumes,
      totalChats,
      upcomingConsultations,
      completedConsultations,
      recentResumes,
      upcomingBookings
    ] = await Promise.all([
      // Total Resumes
      Resume.countDocuments({ userId: userObjectId }),

      // Total Chat Sessions
      ChatSession.countDocuments({ userId: userObjectId }),

      // Upcoming Consultations
      Booking.countDocuments({
        userId: userObjectId,
        status: { $in: ['PAID', 'CONFIRMED'] },
        startTime: { $gte: now }
      }),

      // Completed Consultations
      Booking.countDocuments({
        userId: userObjectId,
        $or: [
          { status: 'COMPLETED' },
          { status: 'CONFIRMED', endTime: { $lt: now } }
        ]
      }),

      // Recent Resumes
      Resume.find({ userId: userObjectId })
        .sort({ updatedAt: -1 })
        .limit(3)
        .select('title template updatedAt'),

      // Upcoming Bookings list
      Booking.find({
        userId: userObjectId,
        status: { $in: ['PENDING_PAYMENT', 'PAID', 'CONFIRMED'] },
        startTime: { $gte: now }
      })
        .populate('consultantId', 'name title avatarUrl')
        .sort({ startTime: 1 })
        .limit(3)
    ]);

    res.status(200).json({
      success: true,
      data: {
        totalResumes,
        totalChats,
        upcomingConsultations,
        completedConsultations,
        recentResumes,
        upcomingBookings
      }
    });
  } catch (err) {
    next(err);
  }
};

