import request from 'supertest';
import app from '../src/app';
import './setup';

describe('Authentication & User Profile API', () => {
  const testUser = {
    name: 'Alice Johnson',
    email: 'alice@example.com',
    password: 'Password123!'
  };

  it('should register a new user successfully', async () => {
    const res = await request(app)
      .post('/api/auth/register')
      .send(testUser);

    expect(res.status).toBe(201);
    expect(res.body.success).toBe(true);
    expect(res.body.data.user.email).toBe(testUser.email);
    expect(res.body.data.token).toBeDefined();
    expect(res.headers['set-cookie']).toBeDefined();
  });

  it('should reject registration with duplicate email', async () => {
    await request(app).post('/api/auth/register').send(testUser);

    const res = await request(app)
      .post('/api/auth/register')
      .send(testUser);

    expect(res.status).toBe(400);
    expect(res.body.success).toBe(false);
    expect(res.body.error.code).toBe('BAD_REQUEST');
  });

  it('should login an existing user with correct credentials', async () => {
    await request(app).post('/api/auth/register').send(testUser);

    const res = await request(app)
      .post('/api/auth/login')
      .send({ email: testUser.email, password: testUser.password });

    expect(res.status).toBe(200);
    expect(res.body.success).toBe(true);
    expect(res.body.data.token).toBeDefined();
  });

  it('should reject login with incorrect password', async () => {
    await request(app).post('/api/auth/register').send(testUser);

    const res = await request(app)
      .post('/api/auth/login')
      .send({ email: testUser.email, password: 'WrongPassword' });

    expect(res.status).toBe(401);
    expect(res.body.success).toBe(false);
  });

  it('should reject unauthenticated request to /api/users/profile', async () => {
    const res = await request(app).get('/api/users/profile');
    expect(res.status).toBe(401);
  });

  it('should get and update user profile when authenticated', async () => {
    const regRes = await request(app).post('/api/auth/register').send(testUser);
    const token = regRes.body.data.token;

    // Get profile
    const getRes = await request(app)
      .get('/api/users/profile')
      .set('Authorization', `Bearer ${token}`);

    expect(getRes.status).toBe(200);
    expect(getRes.body.data.email).toBe(testUser.email);

    // Update profile
    const updateRes = await request(app)
      .patch('/api/users/profile')
      .set('Authorization', `Bearer ${token}`)
      .send({
        headline: 'Senior Cloud Architect',
        bio: 'Passionate about distributed microservices and AI.',
        skills: ['TypeScript', 'Node.js', 'AWS', 'MongoDB']
      });

    expect(updateRes.status).toBe(200);
    expect(updateRes.body.data.profile.headline).toBe('Senior Cloud Architect');
    expect(updateRes.body.data.profile.skills).toContain('AWS');
  });
});

import request from 'supertest';
import app from '../src/app';
import './setup';

describe('Resume Management & AI Section Generation API', () => {
  let userTokenA: string;
  let userTokenB: string;

  beforeEach(async () => {
    const resA = await request(app).post('/api/auth/register').send({
      name: 'User A',
      email: 'usera@example.com',
      password: 'Password123!'
    });
    userTokenA = resA.body.data.token;

    const resB = await request(app).post('/api/auth/register').send({
      name: 'User B',
      email: 'userb@example.com',
      password: 'Password123!'
    });
    userTokenB = resB.body.data.token;
  });

  it('should create, retrieve, update, and delete a structured resume', async () => {
    // 1. Create
    const createRes = await request(app)
      .post('/api/resumes')
      .set('Authorization', `Bearer ${userTokenA}`)
      .send({
        title: 'Software Engineer Resume',
        template: 'MODERN_PROFESSIONAL'
      });

    expect(createRes.status).toBe(201);
    const resumeId = createRes.body.data.resume._id;

    // 2. Update structured sections
    const updateRes = await request(app)
      .patch(`/api/resumes/${resumeId}`)
      .set('Authorization', `Bearer ${userTokenA}`)
      .send({
        personalInfo: {
          fullName: 'Alice Johnson',
          email: 'alice@example.com',
          phone: '+1-555-0199',
          location: 'Seattle, WA',
          linkedin: 'https://linkedin.com/in/alicej'
        },
        summary: 'Experienced full stack developer with 6 years building distributed applications.',
        skills: ['TypeScript', 'React', 'Node.js', 'MongoDB'],
        experience: [
          {
            company: 'Acme Corp',
            role: 'Lead Developer',
            location: 'Seattle, WA',
            startDate: '2021-01',
            endDate: 'Present',
            current: true,
            description: 'Managing a team of 5 engineers.',
            highlights: ['Increased API throughput by 40%']
          }
        ]
      });

    expect(updateRes.status).toBe(200);
    expect(updateRes.body.data.resume.personalInfo.fullName).toBe('Alice Johnson');
    expect(updateRes.body.data.resume.skills).toContain('TypeScript');

    // 3. Template switching preserves structured data
    const switchRes = await request(app)
      .patch(`/api/resumes/${resumeId}`)
      .set('Authorization', `Bearer ${userTokenA}`)
      .send({ template: 'ATS_CLASSIC' });

    expect(switchRes.status).toBe(200);
    expect(switchRes.body.data.resume.template).toBe('ATS_CLASSIC');
    expect(switchRes.body.data.resume.personalInfo.fullName).toBe('Alice Johnson');
    expect(switchRes.body.data.resume.skills).toContain('TypeScript');

    // 4. Export preview
    const exportRes = await request(app)
      .get(`/api/resumes/${resumeId}/export`)
      .set('Authorization', `Bearer ${userTokenA}`);

    expect(exportRes.status).toBe(200);
    expect(exportRes.body.data.html).toContain('Alice Johnson');
    expect(exportRes.body.data.html).toContain('Lead Developer');

    // 5. Delete
    const deleteRes = await request(app)
      .delete(`/api/resumes/${resumeId}`)
      .set('Authorization', `Bearer ${userTokenA}`);

    expect(deleteRes.status).toBe(200);

    // Verify gone
    const getRes = await request(app)
      .get(`/api/resumes/${resumeId}`)
      .set('Authorization', `Bearer ${userTokenA}`);

    expect(getRes.status).toBe(404);
  });

  it('should prevent User B from accessing or updating User A resume', async () => {
    const createRes = await request(app)
      .post('/api/resumes')
      .set('Authorization', `Bearer ${userTokenA}`)
      .send({ title: 'User A Private Resume' });

    const resumeId = createRes.body.data.resume._id;

    // User B tries to view
    const viewRes = await request(app)
      .get(`/api/resumes/${resumeId}`)
