describe('AI Career Assistant Chat API', () => {
  let userTokenA: string;
  let userTokenB: string;

  beforeEach(async () => {
    const resA = await request(app).post('/api/auth/register').send({
      name: 'Chat User A',
      email: 'chata@example.com',
      password: 'Password123!'
    });
    userTokenA = resA.body.data.token;

    const resB = await request(app).post('/api/auth/register').send({
      name: 'Chat User B',
      email: 'chatb@example.com',
      password: 'Password123!'
    });
    userTokenB = resB.body.data.token;
  });

  it('should create session, exchange messages, and preserve conversation history', async () => {
    // 1. Create session
    const sessionRes = await request(app)
      .post('/api/chat/sessions')
      .set('Authorization', `Bearer ${userTokenA}`)
      .send({ title: 'Interview Strategy Session' });

    expect(sessionRes.status).toBe(201);
    const sessionId = sessionRes.body.data.session._id;

    // 2. Send message
    const msgRes = await request(app)
      .post(`/api/chat/sessions/${sessionId}/messages`)
      .set('Authorization', `Bearer ${userTokenA}`)
      .send({ content: 'How should I prepare for a senior engineer interview?' });

