    expect(msgRes.body.data.userMessage.content).toBe('How should I prepare for a senior engineer interview?');
    expect(msgRes.body.data.assistantMessage.content).toBeDefined();
    expect(msgRes.body.data.assistantMessage.role).toBe('assistant');

    // 3. Fetch session history
    const historyRes = await request(app)
      .get(`/api/chat/sessions/${sessionId}`)
      .set('Authorization', `Bearer ${userTokenA}`);

    expect(historyRes.status).toBe(200);
    expect(historyRes.body.data.messages.length).toBe(2);

