  });
});

import request from 'supertest';
import app from '../src/app';
import { Consultant } from '../src/modules/consultants/consultant.model';
import './setup';

describe('Consultation Booking & Concurrency Safeguards API', () => {
  let userToken: string;
  let consultantId: string;

  beforeEach(async () => {
    const regRes = await request(app).post('/api/auth/register').send({
      name: 'Booking Client',
      email: 'client@example.com',
      password: 'Password123!'
    });
    userToken = regRes.body.data.token;

    const consultant = await Consultant.create({
      name: 'Elena Rostova',
      title: 'Staff Software Architect',
      bio: 'Expert in cloud architectures and hiring loops.',
      email: 'elena@consultants.com',
      hourlyRate: 18000, // $180.00
      durationMinutes: 45,
      isActive: true,
      availability: [{ dayOfWeek: 1, startTime: '09:00', endTime: '18:00' }]
    });
    consultantId = consultant._id.toString();
  });

  it('should reject bookings scheduled in the past', async () => {
    const pastDate = new Date(Date.now() - 24 * 60 * 60 * 1000).toISOString();

    const res = await request(app)
      .post('/api/bookings')
      .set('Authorization', `Bearer ${userToken}`)
      .send({
        consultantId,
        startTime: pastDate,
        userName: 'Booking Client',
        userEmail: 'client@example.com',
        agenda: 'Review my resume and discuss mock interview'
      });

    expect(res.status).toBe(400);
    expect(res.body.error.message).toContain('past');
  });

  it('should successfully create a pending booking and prevent double booking of overlapping slot', async () => {
    // Schedule 3 days in the future
    const futureDate = new Date(Date.now() + 3 * 24 * 60 * 60 * 1000);
    futureDate.setUTCHours(14, 0, 0, 0);
    const startTimeIso = futureDate.toISOString();

    // 1. Initial valid booking
    const bookingRes1 = await request(app)
      .post('/api/bookings')
      .set('Authorization', `Bearer ${userToken}`)
      .send({
        consultantId,
        startTime: startTimeIso,
        userName: 'Booking Client',
        userEmail: 'client@example.com',
        agenda: 'Career strategy planning'
      });

    expect(bookingRes1.status).toBe(201);
    expect(bookingRes1.body.data.booking.status).toBe('PENDING_PAYMENT');
    expect(bookingRes1.body.data.booking.amount).toBe(18000); // Server-calculated

    // 2. Concurrency safeguard: attempt to book overlapping slot (same time)
    const bookingRes2 = await request(app)
      .post('/api/bookings')
      .set('Authorization', `Bearer ${userToken}`)
      .send({
        consultantId,
        startTime: startTimeIso,
        userName: 'Another Client',
        userEmail: 'another@example.com',
        agenda: 'Overlapping request'
      });

    expect(bookingRes2.status).toBe(409); // Conflict error
    expect(bookingRes2.body.error.code).toBe('CONFLICT');
  });

  it('should support server-side pagination, search, sorting, and filtering', async () => {
    // Create two distinct bookings
    const futureDate1 = new Date(Date.now() + 2 * 24 * 60 * 60 * 1000);
    futureDate1.setUTCHours(10, 0, 0, 0);

    const futureDate2 = new Date(Date.now() + 4 * 24 * 60 * 60 * 1000);
    futureDate2.setUTCHours(15, 0, 0, 0);

    await request(app)
      .post('/api/bookings')
      .set('Authorization', `Bearer ${userToken}`)
      .send({
        consultantId,
        startTime: futureDate1.toISOString(),
        userName: 'Booking Client',
        userEmail: 'client@example.com',
        agenda: 'Frontend architecture discussion'
      });

    await request(app)
      .post('/api/bookings')
      .set('Authorization', `Bearer ${userToken}`)
      .send({
        consultantId,
        startTime: futureDate2.toISOString(),
        userName: 'Booking Client',
        userEmail: 'client@example.com',
        agenda: 'Backend system design'
      });

    // Test listing with pagination and search
    const listRes = await request(app)
      .get('/api/bookings?page=1&limit=10&search=Frontend&status=PENDING_PAYMENT')
      .set('Authorization', `Bearer ${userToken}`);

    expect(listRes.status).toBe(200);
    expect(listRes.body.data.length).toBe(1);
    expect(listRes.body.data[0].agenda).toContain('Frontend');
    expect(listRes.body.pagination.total).toBe(1);
    expect(listRes.body.pagination.page).toBe(1);
  });
});

import request from 'supertest';
import app from '../src/app';
import { Consultant } from '../src/modules/consultants/consultant.model';
import { Booking } from '../src/modules/bookings/booking.model';
import { Payment } from '../src/modules/payments/payment.model';
import './setup';

describe('Stripe Payments & Webhook Idempotency API', () => {
  let userToken: string;
  let bookingId: string;

  beforeEach(async () => {
    const regRes = await request(app).post('/api/auth/register').send({
      name: 'Payment Tester',
      email: 'payer@example.com',
      password: 'Password123!'
    });
    userToken = regRes.body.data.token;

    const consultant = await Consultant.create({
      name: 'Marcus Brody',
      title: 'Principal Career Consultant',
      bio: 'Executive coach.',
      email: 'marcus@consultants.com',
      hourlyRate: 15000,
      durationMinutes: 45,
      isActive: true,
      availability: [{ dayOfWeek: 2, startTime: '09:00', endTime: '18:00' }]
    });

    const futureDate = new Date(Date.now() + 5 * 24 * 60 * 60 * 1000);
    futureDate.setUTCHours(11, 0, 0, 0);

    const booking = await Booking.create({
      userId: regRes.body.data.user.id,
      consultantId: consultant._id,
      userName: 'Payment Tester',
      userEmail: 'payer@example.com',
      agenda: 'Salary negotiation and portfolio review',
      startTime: futureDate,
      endTime: new Date(futureDate.getTime() + 45 * 60 * 1000),
      durationMinutes: 45,
      amount: 15000,
      status: 'PENDING_PAYMENT'
    });
    bookingId = booking._id.toString();
  });

  it('should create a checkout session for a pending booking', async () => {
    const res = await request(app)
      .post('/api/payments/checkout')
      .set('Authorization', `Bearer ${userToken}`)
      .send({ bookingId });

    expect(res.status).toBe(200);
    expect(res.body.success).toBe(true);
    expect(res.body.data.checkoutUrl).toBeDefined();
    expect(res.body.data.sessionId).toBeDefined();

    const payment = await Payment.findOne({ bookingId });
    expect(payment).toBeDefined();
    expect(payment?.amount).toBe(15000); // Verified server-side price
    expect(payment?.status).toBe('PENDING');
  });

  it('should process webhook idempotently and transition booking to CONFIRMED', async () => {
    // 1. Initialize checkout
    const checkoutRes = await request(app)
      .post('/api/payments/checkout')
      .set('Authorization', `Bearer ${userToken}`)
      .send({ bookingId });

    const sessionId = checkoutRes.body.data.sessionId;
    const eventId = `evt_test_${Date.now()}`;

    // 2. Deliver webhook event
    const webhookPayload = {
      id: eventId,
      type: 'checkout.session.completed',
      data: {
        object: {
          id: sessionId,
          client_reference_id: bookingId,
          payment_intent: 'pi_test_123456789',
          metadata: { bookingId }
        }
      }
    };

    const webhookRes = await request(app)
      .post('/api/payments/webhook')
      .send(webhookPayload);

    expect(webhookRes.status).toBe(200);
    expect(webhookRes.body.received).toBe(true);

    // Verify booking updated to CONFIRMED and has meeting link
    const updatedBooking = await Booking.findById(bookingId);
    expect(updatedBooking?.status).toBe('CONFIRMED');
    expect(updatedBooking?.meetingUrl).toBeDefined();
    expect(updatedBooking?.calendarStatus).toBe('SCHEDULED');

    const updatedPayment = await Payment.findOne({ bookingId });
    expect(updatedPayment?.status).toBe('SUCCEEDED');
    expect(updatedPayment?.processedWebhookEvents).toContain(eventId);

    // 3. Duplicate webhook test: send the same event again
    const duplicateRes = await request(app)
      .post('/api/payments/webhook')
      .send(webhookPayload);

    expect(duplicateRes.status).toBe(200);
    expect(duplicateRes.body.duplicate).toBe(true);

    // Ensure status remains confirmed and not corrupted
    const recheckedBooking = await Booking.findById(bookingId);
    expect(recheckedBooking?.status).toBe('CONFIRMED');
  });
});

