const BACKEND_URL = process.env.NEXT_PUBLIC_BACKEND_URL || 'http://localhost:5000';

class ApiClient {
  private token: string | null = null;

  constructor() {
    if (typeof window !== 'undefined') {
      this.token = sessionStorage.getItem('auth_token');
    }
  }

  setToken(token: string | null) {
    this.token = token;
    if (typeof window !== 'undefined') {
      if (token) {
        sessionStorage.setItem('auth_token', token);
      } else {
        sessionStorage.removeItem('auth_token');
      }
    }
  }

  getToken(): string | null {
    if (!this.token && typeof window !== 'undefined') {
      this.token = sessionStorage.getItem('auth_token');
    }
    return this.token;
  }

  private async request<T>(endpoint: string, options: RequestInit = {}): Promise<T> {
    const url = `${BACKEND_URL}${endpoint}`;
    const token = this.getToken();

    const headers: Record<string, string> = {
      'Content-Type': 'application/json',
      ...(options.headers as Record<string, string>),
    };

    if (token) {
      headers['Authorization'] = `Bearer ${token}`;
    }

    const response = await fetch(url, {
      ...options,
      headers,
      credentials: 'include', // Includes HTTP-only cookies
    });

    const data = await response.json().catch(() => ({}));

    if (!response.ok) {
      const errorMessage = data?.error?.message || response.statusText || 'Request failed';
      throw new Error(errorMessage);
    }

    return data;
  }

  // AUTH
  async register(body: any) {
    const res = await this.request<any>('/api/auth/register', {
      method: 'POST',
      body: JSON.stringify(body),
    });
    if (res?.data?.token) {
      this.setToken(res.data.token);
    }
    return res;
  }

  async login(body: any) {
    const res = await this.request<any>('/api/auth/login', {
      method: 'POST',
      body: JSON.stringify(body),
    });
    if (res?.data?.token) {
      this.setToken(res.data.token);
    }
    return res;
  }

  async logout() {
    try {
      await this.request('/api/auth/logout', { method: 'POST' });
    } finally {
      this.setToken(null);
    }
  }

  async getMe() {
    return this.request<any>('/api/auth/me');
  }

  // PROFILE
  async getProfile() {
    return this.request<any>('/api/users/profile');
  }

  async updateProfile(body: any) {
    return this.request<any>('/api/users/profile', {
      method: 'PATCH',
      body: JSON.stringify(body),
    });
  }

  // CHAT
  async getChatSessions() {
    return this.request<any>('/api/chat/sessions');
  }

  async createChatSession(title?: string) {
    return this.request<any>('/api/chat/sessions', {
      method: 'POST',
      body: JSON.stringify({ title }),
    });
  }

  async getChatSession(sessionId: string) {
    return this.request<any>(`/api/chat/sessions/${sessionId}`);
  }

  async updateChatSession(sessionId: string, title: string) {
    return this.request<any>(`/api/chat/sessions/${sessionId}`, {
      method: 'PATCH',
      body: JSON.stringify({ title }),
    });
  }

  async deleteChatSession(sessionId: string) {
    return this.request<any>(`/api/chat/sessions/${sessionId}`, {
      method: 'DELETE',
    });
  }

  async sendChatMessage(sessionId: string, content: string) {
    return this.request<any>(`/api/chat/sessions/${sessionId}/messages`, {
      method: 'POST',
      body: JSON.stringify({ content }),
    });
  }

  // RESUMES
  async getResumes() {
    return this.request<any>('/api/resumes');
  }

  async createResume(title: string, template: string) {
    return this.request<any>('/api/resumes', {
      method: 'POST',
      body: JSON.stringify({ title, template }),
    });
  }

  async getResume(id: string) {
    return this.request<any>(`/api/resumes/${id}`);
  }

  async updateResume(id: string, body: any) {
    return this.request<any>(`/api/resumes/${id}`, {
      method: 'PATCH',
      body: JSON.stringify(body),
    });
  }

  async deleteResume(id: string) {
    return this.request<any>(`/api/resumes/${id}`, {
      method: 'DELETE',
    });
  }

  async generateResumeSection(id: string, section: string, prompt: string) {
    return this.request<any>(`/api/resumes/${id}/generate`, {
      method: 'POST',
      body: JSON.stringify({ section, prompt }),
    });
  }

  async exportResume(id: string, template?: string) {
    const query = template ? `?template=${template}` : '';
    return this.request<any>(`/api/resumes/${id}/export${query}`);
  }

  // CONSULTANTS
  async getConsultants(search?: string, expertise?: string) {
    const params = new URLSearchParams();
    if (search) params.append('search', search);
    if (expertise) params.append('expertise', expertise);
    return this.request<any>(`/api/consultants?${params.toString()}`);
  }

  async getConsultantById(id: string) {
    return this.request<any>(`/api/consultants/${id}`);
  }

  async getConsultantAvailability(id: string, date: string) {
    return this.request<any>(`/api/consultants/${id}/availability?date=${date}`);
  }

  // BOOKINGS
  async getBookings(page = 1, limit = 10, status?: string, search?: string) {
    const params = new URLSearchParams({ page: String(page), limit: String(limit) });
    if (status) params.append('status', status);
    if (search) params.append('search', search);
    return this.request<any>(`/api/bookings?${params.toString()}`);
  }

  async createBooking(body: any) {
    return this.request<any>('/api/bookings', {
      method: 'POST',
      body: JSON.stringify(body),
    });
  }

  async cancelBooking(id: string) {
    return this.request<any>(`/api/bookings/${id}/cancel`, {
      method: 'PATCH',
    });
  }

  // PAYMENTS
  async createCheckoutSession(bookingId: string) {
    return this.request<any>('/api/payments/checkout', {
      method: 'POST',
      body: JSON.stringify({ bookingId }),
    });
  }

  async getPaymentStatus(bookingId?: string, sessionId?: string) {
    const query = bookingId ? `/${bookingId}` : `?sessionId=${sessionId}`;
    return this.request<any>(`/api/payments/status${query}`);
  }

  // DASHBOARD
  async getDashboardMetrics() {
    return this.request<any>('/api/dashboard');
  }
}

export const api = new ApiClient();

