      await api.logout();
    } finally {
      router.push('/login');
    }
  };

  const navItems = [
    { label: 'Dashboard', href: '/dashboard', icon: LayoutDashboard },
    { label: 'AI Career Assistant', href: '/chat', icon: BotMessageSquare },
    { label: 'My Resumes', href: '/resumes', icon: FileText },
    { label: 'Create Resume', href: '/resumes/create', icon: FilePlus },
    { label: 'Consultations', href: '/consultations', icon: CalendarCheck },
    { label: 'Profile', href: '/profile', icon: User },
