import React, { useEffect } from 'react';
import { useEditor, EditorContent } from '@tiptap/react';
import StarterKit from '@tiptap/starter-kit';
import {
  Bold,
  Italic,
  List,
  ListOrdered,
  Heading1,
  Heading2,
  Undo,
  Redo
} from 'lucide-react';
import { cn } from '@/lib/utils';

export interface TiptapResumeEditorProps {
  content: string;
  onChange: (newContent: string) => void;
  editable?: boolean;
}

export const TiptapResumeEditor: React.FC<TiptapResumeEditorProps> = ({
  content,
  onChange,
  editable = true,
}) => {
  const editor = useEditor({
    extensions: [
      StarterKit.configure({
        heading: { levels: [1, 2, 3] },
      }),
    ],
    content: content || '<p>Start typing your professional experience or summary...</p>',
    editable,
    onUpdate: ({ editor }) => {
      onChange(editor.getHTML());
    },
  });

  // Synchronize when external content changes
  useEffect(() => {
    if (editor && content !== editor.getHTML()) {
      editor.commands.setContent(content || '<p></p>');
    }
  }, [content, editor]);

  if (!editor) {
    return (
      <div className="h-48 rounded-lg border border-slate-200 bg-slate-50 animate-pulse flex items-center justify-center text-slate-400">
        Loading editor...
      </div>
    );
  }

  return (
    <div className="rounded-xl border border-slate-200 bg-white shadow-sm overflow-hidden">
      {/* Editor Toolbar */}
      {editable && (
        <div className="flex flex-wrap items-center gap-1 border-b border-slate-200 bg-slate-50/70 p-2 text-slate-700">
          <button
            type="button"
            onClick={() => editor.chain().focus().toggleBold().run()}
            className={cn(
              'p-1.5 rounded hover:bg-slate-200 transition-colors',
              editor.isActive('bold') && 'bg-blue-100 text-blue-700 font-bold'
            )}
            title="Bold"
          >
            <Bold className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => editor.chain().focus().toggleItalic().run()}
            className={cn(
              'p-1.5 rounded hover:bg-slate-200 transition-colors',
              editor.isActive('italic') && 'bg-blue-100 text-blue-700'
            )}
            title="Italic"
          >
            <Italic className="w-4 h-4" />
          </button>
          <div className="w-[1px] h-5 bg-slate-300 mx-1" />
          <button
            type="button"
            onClick={() => editor.chain().focus().toggleHeading({ level: 1 }).run()}
            className={cn(
              'p-1.5 rounded hover:bg-slate-200 transition-colors',
              editor.isActive('heading', { level: 1 }) && 'bg-blue-100 text-blue-700'
            )}
            title="Heading 1"
          >
            <Heading1 className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => editor.chain().focus().toggleHeading({ level: 2 }).run()}
            className={cn(
              'p-1.5 rounded hover:bg-slate-200 transition-colors',
              editor.isActive('heading', { level: 2 }) && 'bg-blue-100 text-blue-700'
            )}
            title="Heading 2"
          >
            <Heading2 className="w-4 h-4" />
          </button>
          <div className="w-[1px] h-5 bg-slate-300 mx-1" />
          <button
            type="button"
            onClick={() => editor.chain().focus().toggleBulletList().run()}
            className={cn(
              'p-1.5 rounded hover:bg-slate-200 transition-colors',
              editor.isActive('bulletList') && 'bg-blue-100 text-blue-700'
            )}
            title="Bullet List"
          >
            <List className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => editor.chain().focus().toggleOrderedList().run()}
            className={cn(
              'p-1.5 rounded hover:bg-slate-200 transition-colors',
              editor.isActive('orderedList') && 'bg-blue-100 text-blue-700'
            )}
            title="Numbered List"
          >
            <ListOrdered className="w-4 h-4" />
          </button>
          <div className="w-[1px] h-5 bg-slate-300 mx-1" />
          <button
            type="button"
            onClick={() => editor.chain().focus().undo().run()}
            disabled={!editor.can().undo()}
            className="p-1.5 rounded hover:bg-slate-200 disabled:opacity-40 transition-colors"
            title="Undo"
          >
            <Undo className="w-4 h-4" />
          </button>
          <button
            type="button"
            onClick={() => editor.chain().focus().redo().run()}
            disabled={!editor.can().redo()}
            className="p-1.5 rounded hover:bg-slate-200 disabled:opacity-40 transition-colors"
            title="Redo"
          >
            <Redo className="w-4 h-4" />
          </button>
        </div>
      )}

      {/* Editor Content Surface */}
      <div className="p-4 min-h-[160px] text-sm text-slate-800 leading-relaxed font-sans">
        <EditorContent editor={editor} />
      </div>
    </div>
  );
};

