'use client';

import React, { useEffect, useState } from 'react';
import { DashboardLayout } from '@/components/layout/DashboardLayout';
import { api } from '@/lib/api';
import { IUser } from '@/types';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Badge } from '@/components/ui/Badge';
import { CheckCircle2, Plus, Trash2 } from 'lucide-react';

export default function ProfilePage() {
  const [user, setUser] = useState<IUser | null>(null);
  const [isLoading, setIsLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [saveSuccess, setSaveSuccess] = useState(false);
  const [newSkill, setNewSkill] = useState('');

  // Form states
  const [name, setName] = useState('');
  const [phone, setPhone] = useState('');
  const [headline, setHeadline] = useState('');
  const [bio, setBio] = useState('');
  const [skills, setSkills] = useState<string[]>([]);

  useEffect(() => {
    api.getProfile()
      .then((res) => {
        if (res?.data) {
          const u = res.data;
          setUser(u);
          setName(u.name || '');
          setPhone(u.profile?.phone || '');
          setHeadline(u.profile?.headline || '');
          setBio(u.profile?.bio || '');
          setSkills(u.profile?.skills || []);
        }
      })
      .catch((err) => console.error(err))
      .finally(() => setIsLoading(false));
  }, []);

  const handleAddSkill = () => {
    if (newSkill.trim() && !skills.includes(newSkill.trim())) {
      setSkills([...skills, newSkill.trim()]);
      setNewSkill('');
    }
  };

  const handleRemoveSkill = (skillToRemove: string) => {
    setSkills(skills.filter(s => s !== skillToRemove));
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    setIsSaving(true);
    setSaveSuccess(false);

    try {
      await api.updateProfile({
        name,
        phone,
        headline,
        bio,
        skills,
      });
      setSaveSuccess(true);
      setTimeout(() => setSaveSuccess(false), 3000);
    } catch (err) {
      console.error('Failed to update profile:', err);
    } finally {
      setIsSaving(false);
    }
  };

  return (
    <DashboardLayout>
      <div className="max-w-4xl space-y-8">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-slate-900">Personal & Professional Profile</h1>
          <p className="text-sm text-slate-500 mt-1">
            Manage your personal contact details, bio, and technical skills used by the AI resume engine.
          </p>
        </div>

        {saveSuccess && (
          <div className="p-4 rounded-xl bg-emerald-50 border border-emerald-200 text-emerald-800 text-sm flex items-center gap-2">
            <CheckCircle2 className="w-5 h-5 text-emerald-600 flex-shrink-0" />
            <span>Profile changes saved successfully!</span>
          </div>
        )}

        <form onSubmit={handleSave} className="space-y-6">
          <Card>
            <CardHeader>
              <CardTitle className="text-base">Basic Information</CardTitle>
              <CardDescription>Your public identity and contact details</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <Input
                  label="Full Name"
                  value={name}
                  onChange={(e) => setName(e.target.value)}
                  placeholder="e.g. Alice Johnson"
                  required
                />
                <Input
                  label="Email Address (Login ID)"
                  value={user?.email || ''}
                  disabled
                  helperText="Email cannot be changed"
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <Input
                  label="Phone Number"
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  placeholder="+1 (555) 000-0000"
                />
                <Input
                  label="Professional Headline"
                  value={headline}
                  onChange={(e) => setHeadline(e.target.value)}
                  placeholder="Senior Software Engineer | Cloud Architect"
                />
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1.5">Biography & Summary</label>
                <textarea
                  rows={4}
                  value={bio}
                  onChange={(e) => setBio(e.target.value)}
                  placeholder="Briefly describe your career journey, leadership style, and key achievements..."
                  className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 placeholder:text-slate-400 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
                />
              </div>
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="text-base">Skills & Competencies</CardTitle>
              <CardDescription>Technical tools, methodologies, and frameworks</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="flex gap-2">
                <Input
                  value={newSkill}
                  onChange={(e) => setNewSkill(e.target.value)}
                  placeholder="Add skill (e.g. Next.js, Kubernetes, PostgreSQL)"
                  onKeyDown={(e) => {
                    if (e.key === 'Enter') {
                      e.preventDefault();
                      handleAddSkill();
                    }
                  }}
                />
                <Button type="button" onClick={handleAddSkill} variant="secondary" className="gap-1 flex-shrink-0">
                  <Plus className="w-4 h-4" /> Add
                </Button>
              </div>

              <div className="flex flex-wrap gap-2 pt-2">
                {skills.length === 0 ? (
                  <p className="text-xs text-slate-400">No skills added yet.</p>
                ) : (
                  skills.map((skill) => (
                    <span
                      key={skill}
                      className="inline-flex items-center gap-1.5 rounded-lg bg-blue-50 border border-blue-200 px-3 py-1 text-xs font-semibold text-blue-700"
                    >
                      {skill}
                      <button
                        type="button"
                        onClick={() => handleRemoveSkill(skill)}
                        className="hover:text-red-600 transition-colors"
                      >
                        <Trash2 className="w-3 h-3" />
                      </button>
                    </span>
                  ))
                )}
              </div>
            </CardContent>
          </Card>

          <div className="flex justify-end">
            <Button type="submit" size="lg" isLoading={isSaving} className="w-full sm:w-auto">
              Save Profile Changes
            </Button>
          </div>
        </form>
      </div>
    </DashboardLayout>
  );
}

'use client';

import React, { useEffect, useState, useRef } from 'react';
import { DashboardLayout } from '@/components/layout/DashboardLayout';
import { api } from '@/lib/api';
import { IChatSession, IChatMessage } from '@/types';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Modal } from '@/components/ui/Modal';
import {
  BotMessageSquare,
  Plus,
  Send,
  MessageSquare,
  Edit2,
  Trash2,
  Sparkles,
  User,
  Loader2
} from 'lucide-react';
import { cn } from '@/lib/utils';

export default function ChatPage() {
  const [sessions, setSessions] = useState<IChatSession[]>([]);
  const [activeSessionId, setActiveSessionId] = useState<string | null>(null);
  const [messages, setMessages] = useState<IChatMessage[]>([]);
  const [inputMessage, setInputMessage] = useState('');
  const [isLoadingSessions, setIsLoadingSessions] = useState(true);
  const [isSending, setIsSending] = useState(false);

  // Rename modal
  const [isRenameOpen, setIsRenameOpen] = useState(false);
  const [renameTitle, setRenameTitle] = useState('');
  const [sessionToRename, setSessionToRename] = useState<string | null>(null);

  const messagesEndRef = useRef<HTMLDivElement>(null);

  const scrollToBottom = () => {
    messagesEndRef.current?.scrollIntoView({ behavior: 'smooth' });
  };

  useEffect(() => {
    loadSessions();
  }, []);

  useEffect(() => {
    if (activeSessionId) {
      loadMessages(activeSessionId);
    }
  }, [activeSessionId]);

  useEffect(() => {
    scrollToBottom();
  }, [messages]);

  const loadSessions = async () => {
    setIsLoadingSessions(true);
    try {
      const res = await api.getChatSessions();
      if (res?.data?.sessions) {
        setSessions(res.data.sessions);
        if (res.data.sessions.length > 0 && !activeSessionId) {
          setActiveSessionId(res.data.sessions[0]._id);
        }
      }
    } catch (err) {
      console.error('Failed to load chat sessions:', err);
    } finally {
      setIsLoadingSessions(false);
    }
  };

  const loadMessages = async (sessionId: string) => {
    try {
      const res = await api.getChatSession(sessionId);
      if (res?.data?.messages) {
        setMessages(res.data.messages);
      }
    } catch (err) {
      console.error('Failed to load session messages:', err);
    }
  };

  const handleCreateSession = async () => {
    try {
      const res = await api.createChatSession('New Career Conversation');
      if (res?.data?.session) {
        const newSession = res.data.session;
        setSessions([newSession, ...sessions]);
        setActiveSessionId(newSession._id);
        setMessages([]);
      }
    } catch (err) {
      console.error('Failed to create new session:', err);
    }
  };

  const handleDeleteSession = async (sessionId: string, e: React.MouseEvent) => {
    e.stopPropagation();
    if (!confirm('Are you sure you want to delete this conversation?')) return;

    try {
      await api.deleteChatSession(sessionId);
      const updated = sessions.filter(s => s._id !== sessionId);
      setSessions(updated);
      if (activeSessionId === sessionId) {
        setActiveSessionId(updated.length > 0 ? updated[0]._id : null);
        setMessages([]);
      }
    } catch (err) {
      console.error('Failed to delete session:', err);
    }
  };

  const openRenameModal = (session: IChatSession, e: React.MouseEvent) => {
    e.stopPropagation();
    setSessionToRename(session._id);
    setRenameTitle(session.title);
    setIsRenameOpen(true);
  };

  const handleSaveRename = async () => {
    if (!sessionToRename || !renameTitle.trim()) return;
    try {
      const res = await api.updateChatSession(sessionToRename, renameTitle.trim());
      if (res?.data?.session) {
        setSessions(sessions.map(s => s._id === sessionToRename ? res.data.session : s));
      }
      setIsRenameOpen(false);
    } catch (err) {
      console.error('Failed to rename session:', err);
    }
  };

  const handleSendMessage = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!inputMessage.trim() || isSending) return;

    let targetSessionId = activeSessionId;
    if (!targetSessionId) {
      // Auto-create session if none active
      const res = await api.createChatSession('New Career Conversation');
      targetSessionId = res.data.session._id;
      setSessions([res.data.session, ...sessions]);
      setActiveSessionId(targetSessionId);
    }

    const currentMsgText = inputMessage.trim();
    setInputMessage('');
    setIsSending(true);

    // Optimistic UI for user message
    const tempUserMsg: IChatMessage = {
      _id: `temp_${Date.now()}`,
      sessionId: targetSessionId!,
      role: 'user',
      content: currentMsgText,
      createdAt: new Date().toISOString(),
    };
    setMessages((prev) => [...prev, tempUserMsg]);

    try {
      const res = await api.sendChatMessage(targetSessionId!, currentMsgText);
      if (res?.data) {
        setMessages((prev) => [
          ...prev.filter(m => m._id !== tempUserMsg._id),
          res.data.userMessage,
          res.data.assistantMessage,
        ]);
        // Refresh session list to show updated title or time
        api.getChatSessions().then(r => setSessions(r.data.sessions));
      }
    } catch (err) {
      console.error('Failed to send message:', err);
    } finally {
      setIsSending(false);
    }
  };

  return (
    <DashboardLayout>
      <div className="h-[calc(100vh-8rem)] flex rounded-2xl border border-slate-200 bg-white shadow-sm overflow-hidden">
        {/* Session List Sidebar */}
        <div className="w-80 border-r border-slate-200 bg-slate-50 flex flex-col">
          <div className="p-4 border-b border-slate-200 flex items-center justify-between">
            <h2 className="text-sm font-bold text-slate-800">Conversations</h2>
            <Button size="sm" onClick={handleCreateSession} className="gap-1.5 text-xs h-8">
              <Plus className="w-3.5 h-3.5" /> New Chat
            </Button>
          </div>

          <div className="flex-1 overflow-y-auto p-3 space-y-1.5">
            {isLoadingSessions ? (
              <div className="p-4 text-center text-xs text-slate-400">Loading chats...</div>
            ) : sessions.length === 0 ? (
              <div className="p-6 text-center text-xs text-slate-400">
                <BotMessageSquare className="w-8 h-8 mx-auto mb-2 opacity-40 text-blue-600" />
                No conversations yet. Click &quot;New Chat&quot; to begin!
              </div>
            ) : (
              sessions.map((s) => {
                const isActive = s._id === activeSessionId;
                return (
                  <div
                    key={s._id}
                    onClick={() => setActiveSessionId(s._id)}
                    className={cn(
                      'group flex items-center justify-between px-3 py-2.5 rounded-xl text-xs font-medium cursor-pointer transition-all',
                      isActive
                        ? 'bg-blue-600 text-white shadow-sm'
                        : 'text-slate-700 hover:bg-slate-200/60'
                    )}
                  >
                    <div className="flex items-center gap-2.5 min-w-0">
                      <MessageSquare className={cn('w-4 h-4 flex-shrink-0', isActive ? 'text-white' : 'text-slate-400')} />
                      <span className="truncate">{s.title}</span>
                    </div>

                    <div className={cn('flex items-center gap-1 opacity-0 group-hover:opacity-100 transition-opacity', isActive && 'opacity-100')}>
                      <button
                        onClick={(e) => openRenameModal(s, e)}
                        className={cn('p-1 rounded hover:bg-black/10', isActive ? 'text-white' : 'text-slate-400 hover:text-slate-600')}
                        title="Rename"
                      >
                        <Edit2 className="w-3 h-3" />
                      </button>
                      <button
                        onClick={(e) => handleDeleteSession(s._id, e)}
                        className={cn('p-1 rounded hover:bg-black/10', isActive ? 'text-white' : 'text-slate-400 hover:text-red-600')}
                        title="Delete"
                      >
                        <Trash2 className="w-3 h-3" />
                      </button>
                    </div>
                  </div>
                );
              })
            )}
          </div>
        </div>

        {/* Active Conversation Area */}
        <div className="flex-1 flex flex-col bg-white">
          {/* Header */}
          <div className="h-14 border-b border-slate-200 px-6 flex items-center justify-between bg-white">
            <div className="flex items-center gap-2">
              <Sparkles className="w-4 h-4 text-blue-600" />
              <span className="text-sm font-semibold text-slate-800">
                {sessions.find(s => s._id === activeSessionId)?.title || 'AI Career Coach'}
              </span>
            </div>
            <span className="text-[11px] text-slate-400">Context active (STAR method & interview prep)</span>
          </div>

          {/* Messages list */}
          <div className="flex-1 overflow-y-auto p-6 space-y-5">
            {messages.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-center max-w-md mx-auto p-6">
                <div className="w-12 h-12 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center mb-4">
                  <BotMessageSquare className="w-6 h-6" />
                </div>
                <h3 className="text-lg font-bold text-slate-900">How can I assist your career today?</h3>
                <p className="text-xs text-slate-500 mt-2 leading-relaxed">
                  Ask for behavioral interview prep, STAR framework restructuring, salary negotiation scripts, or targeted resume critique.
                </p>
                <div className="mt-6 flex flex-wrap gap-2 justify-center">
                  <button
                    onClick={() => setInputMessage('How do I answer "Tell me about a time you handled a difficult conflict"?')}
                    className="text-xs text-left px-3 py-2 rounded-lg bg-slate-50 border border-slate-200 hover:border-blue-400 hover:bg-blue-50 transition-all text-slate-700"
                  >
                    💡 Practice conflict resolution question
                  </button>
                  <button
                    onClick={() => setInputMessage('Give me a strategic salary negotiation framework for a senior offer.')}
                    className="text-xs text-left px-3 py-2 rounded-lg bg-slate-50 border border-slate-200 hover:border-blue-400 hover:bg-blue-50 transition-all text-slate-700"
                  >
                    📈 Senior salary negotiation framework
                  </button>
                </div>
              </div>
            ) : (
              messages.map((m) => {
                const isUser = m.role === 'user';
                return (
                  <div key={m._id} className={cn('flex gap-3', isUser ? 'justify-end' : 'justify-start')}>
                    {!isUser && (
                      <div className="w-8 h-8 rounded-full bg-blue-600 text-white flex items-center justify-center flex-shrink-0 shadow-sm mt-0.5">
                        <BotMessageSquare className="w-4 h-4" />
                      </div>
                    )}

                    <div
                      className={cn(
                        'max-w-[75%] rounded-2xl px-4 py-3 text-sm leading-relaxed whitespace-pre-wrap shadow-sm',
                        isUser
                          ? 'bg-blue-600 text-white rounded-tr-none'
                          : 'bg-slate-50 border border-slate-200 text-slate-800 rounded-tl-none'
                      )}
                    >
                      {m.content}
                    </div>

                    {isUser && (
                      <div className="w-8 h-8 rounded-full bg-slate-200 text-slate-700 flex items-center justify-center flex-shrink-0 shadow-sm mt-0.5">
                        <User className="w-4 h-4" />
                      </div>
                    )}
                  </div>
                );
              })
            )}

            {isSending && (
              <div className="flex gap-3 justify-start items-center text-slate-400 text-xs">
                <div className="w-8 h-8 rounded-full bg-blue-600 text-white flex items-center justify-center flex-shrink-0 shadow-sm">
                  <BotMessageSquare className="w-4 h-4" />
                </div>
                <div className="flex items-center gap-2 bg-slate-50 border border-slate-200 px-4 py-2.5 rounded-2xl rounded-tl-none">
                  <Loader2 className="w-3.5 h-3.5 animate-spin text-blue-600" />
                  <span>AI coach is formulating advice...</span>
                </div>
              </div>
            )}
            <div ref={messagesEndRef} />
          </div>

          {/* Input Form */}
          <div className="p-4 border-t border-slate-200 bg-white">
            <form onSubmit={handleSendMessage} className="flex gap-2">
              <input
                type="text"
                value={inputMessage}
                onChange={(e) => setInputMessage(e.target.value)}
                placeholder="Ask your AI Career Coach anything..."
                className="flex-1 rounded-xl border border-slate-300 bg-white px-4 py-3 text-sm text-slate-900 placeholder:text-slate-400 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
              />
              <Button type="submit" isLoading={isSending} disabled={!inputMessage.trim()} className="px-5 rounded-xl">
                <Send className="w-4 h-4" />
              </Button>
            </form>
          </div>
        </div>
      </div>

      {/* Rename Modal */}
      <Modal isOpen={isRenameOpen} onClose={() => setIsRenameOpen(false)} title="Rename Conversation">
        <div className="space-y-4">
          <Input
            label="Conversation Title"
            value={renameTitle}
            onChange={(e) => setRenameTitle(e.target.value)}
            placeholder="e.g. Senior Backend Interview Prep"
          />
          <div className="flex justify-end gap-2 pt-2">
            <Button variant="outline" onClick={() => setIsRenameOpen(false)}>Cancel</Button>
            <Button onClick={handleSaveRename}>Save</Button>
          </div>
        </div>
      </Modal>
    </DashboardLayout>
  );
}

