'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { DashboardLayout } from '@/components/layout/DashboardLayout';
import { api } from '@/lib/api';
import { IResume } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import { Skeleton } from '@/components/ui/Skeleton';
import { formatDate } from '@/lib/utils';
import {
  FileText,
  Plus,
  Eye,
  Edit,
  Trash2,
  Download,
  Sparkles
} from 'lucide-react';

export default function ResumesListPage() {
  const [resumes, setResumes] = useState<IResume[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    loadResumes();
  }, []);

  const loadResumes = async () => {
    try {
      const res = await api.getResumes();
      if (res?.data?.resumes) {
        setResumes(res.data.resumes);
      }
    } catch (err) {
      console.error('Failed to load resumes:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleDelete = async (id: string, title: string) => {
    if (!confirm(`Are you sure you want to delete "${title}"?`)) return;
    try {
      await api.deleteResume(id);
      setResumes(resumes.filter(r => r._id !== id));
    } catch (err) {
      console.error('Failed to delete resume:', err);
    }
  };

  return (
    <DashboardLayout>
      <div className="space-y-8">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold tracking-tight text-slate-900">My Resumes</h1>
            <p className="text-sm text-slate-500 mt-1">
              Create, edit, and export tailored ATS-friendly and Modern Professional resumes.
            </p>
          </div>
          <Link href="/resumes/create">
            <Button className="gap-2">
              <Plus className="w-4 h-4" /> Create New Resume
            </Button>
          </Link>
        </div>

        {loading ? (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            <Skeleton className="h-48 w-full" />
            <Skeleton className="h-48 w-full" />
            <Skeleton className="h-48 w-full" />
          </div>
        ) : resumes.length === 0 ? (
          <Card className="py-16 text-center">
            <div className="w-12 h-12 rounded-2xl bg-blue-50 text-blue-600 flex items-center justify-center mx-auto mb-4">
              <FileText className="w-6 h-6" />
            </div>
            <h3 className="text-lg font-bold text-slate-900">No resumes created yet</h3>
            <p className="text-sm text-slate-500 max-w-sm mx-auto mt-1 mb-6">
              Start building your professional resume with AI-assisted bullet points and ATS optimization.
            </p>
            <Link href="/resumes/create">
              <Button className="gap-2">
                <Plus className="w-4 h-4" /> Create Your First Resume
              </Button>
            </Link>
          </Card>
        ) : (
          <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 gap-6">
            {resumes.map((resume) => (
              <Card key={resume._id} className="flex flex-col justify-between hover:border-slate-300 transition-all">
                <CardHeader>
                  <div className="flex items-start justify-between gap-2">
                    <CardTitle className="text-base font-bold line-clamp-1">
                      {resume.title}
                    </CardTitle>
                    <Badge variant={resume.template === 'ATS_CLASSIC' ? 'neutral' : 'primary'}>
                      {resume.template === 'ATS_CLASSIC' ? 'ATS Classic' : 'Modern Professional'}
                    </Badge>
                  </div>
                  <p className="text-xs text-slate-400 mt-1">
                    Last updated {formatDate(resume.updatedAt)}
                  </p>
                </CardHeader>

                <CardContent>
                  <p className="text-xs text-slate-600 line-clamp-2 mb-4">
                    {resume.summary ? resume.summary.replace(/<[^>]+>/g, '') : 'No summary provided yet.'}
                  </p>

                  <div className="flex flex-wrap gap-1 mb-4">
                    {resume.skills?.slice(0, 4).map((s, idx) => (
                      <span key={idx} className="px-2 py-0.5 rounded bg-slate-100 text-[11px] text-slate-600 font-medium">
                        {s}
                      </span>
                    ))}
                    {(resume.skills?.length || 0) > 4 && (
                      <span className="text-[11px] text-slate-400 self-center">
                        +{(resume.skills?.length || 0) - 4} more
                      </span>
                    )}
                  </div>

                  <div className="pt-4 border-t border-slate-100 flex items-center justify-between">
                    <div className="flex items-center gap-1">
                      <Link href={`/resumes/${resume._id}/edit`}>
                        <Button size="sm" variant="ghost" className="gap-1.5 text-xs text-blue-600">
                          <Edit className="w-3.5 h-3.5" /> Edit
                        </Button>
                      </Link>
                      <Link href={`/resumes/${resume._id}/preview`}>
                        <Button size="sm" variant="ghost" className="gap-1.5 text-xs text-slate-600">
                          <Eye className="w-3.5 h-3.5" /> Preview
                        </Button>
                      </Link>
                    </div>

                    <button
                      onClick={() => handleDelete(resume._id, resume.title)}
                      className="p-1.5 rounded-lg text-slate-400 hover:text-red-600 hover:bg-red-50 transition-colors"
                      title="Delete resume"
                    >
                      <Trash2 className="w-4 h-4" />
                    </button>
                  </div>
                </CardContent>
              </Card>
            ))}
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

