export default function CreateResumePage() {
  const router = useRouter();
  const [title, setTitle] = useState('');
  const [selectedTemplate, setSelectedTemplate] = useState<ResumeTemplateType>('MODERN_PROFESSIONAL');
  const [isLoading, setIsLoading] = useState(false);

  const handleCreate = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!title.trim() || isLoading) return;

    setIsLoading(true);
    try {
      const res = await api.createResume(title.trim(), selectedTemplate);
      if (res?.data?.resume?._id) {
        router.push(`/resumes/${res.data.resume._id}/edit`);
      }
    } catch (err) {
      console.error('Failed to create resume:', err);
      setIsLoading(false);
    }
  };

  return (
    <DashboardLayout>
