          <h1 className="text-2xl font-bold tracking-tight text-slate-900">Create a New Resume</h1>
          <p className="text-sm text-slate-500 mt-1">
            Choose a starting template. You can switch templates anytime without losing content.
          </p>
        </div>

        <form onSubmit={handleCreate} className="space-y-6">
