              <Input
                label="Resume Title"
                value={title}
                onChange={(e) => setTitle(e.target.value)}
                placeholder="e.g. Senior Backend Engineer - Target: FinTech"
                required
              />
            </CardContent>
          </Card>

          <Card>
            <CardHeader>
              <CardTitle className="text-base">Select Starting Template</CardTitle>
              <CardDescription>Choose how you would like your resume presented</CardDescription>
            </CardHeader>
            <CardContent>
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Modern Professional */}
                <div
                  onClick={() => setSelectedTemplate('MODERN_PROFESSIONAL')}
                  className={cn(
                    'p-5 rounded-xl border-2 cursor-pointer transition-all flex flex-col justify-between relative',
                    selectedTemplate === 'MODERN_PROFESSIONAL'
                      ? 'border-blue-600 bg-blue-50/40'
                      : 'border-slate-200 hover:border-slate-300 bg-white'
                  )}
                >
                  {selectedTemplate === 'MODERN_PROFESSIONAL' && (
                    <div className="absolute top-3 right-3 w-5 h-5 rounded-full bg-blue-600 text-white flex items-center justify-center">
                      <Check className="w-3.5 h-3.5" />
                    </div>
                  )}
                  <div>
                    <div className="w-9 h-9 rounded-lg bg-blue-100 text-blue-600 flex items-center justify-center mb-3">
                      <Layout className="w-5 h-5" />
                    </div>
                    <h4 className="font-bold text-slate-900 text-sm">Modern Professional</h4>
                    <p className="text-xs text-slate-500 mt-1 leading-relaxed">
                      Contemporary typography, subtle accent borders, balanced whitespace, and clear visual hierarchy.
                    </p>
                  </div>
                </div>

                {/* ATS Classic */}
                <div
                  onClick={() => setSelectedTemplate('ATS_CLASSIC')}
                  className={cn(
                    'p-5 rounded-xl border-2 cursor-pointer transition-all flex flex-col justify-between relative',
                    selectedTemplate === 'ATS_CLASSIC'
                      ? 'border-blue-600 bg-blue-50/40'
                      : 'border-slate-200 hover:border-slate-300 bg-white'
                  )}
                >
                  {selectedTemplate === 'ATS_CLASSIC' && (
                    <div className="absolute top-3 right-3 w-5 h-5 rounded-full bg-blue-600 text-white flex items-center justify-center">
                      <Check className="w-3.5 h-3.5" />
                    </div>
                  )}
                  <div>
                    <div className="w-9 h-9 rounded-lg bg-slate-100 text-slate-700 flex items-center justify-center mb-3">
                      <AlignLeft className="w-5 h-5" />
                    </div>
                    <h4 className="font-bold text-slate-900 text-sm">ATS Classic</h4>
                    <p className="text-xs text-slate-500 mt-1 leading-relaxed">
                      Single-column, conventional layout designed for maximum ATS machine-readability and keyword extraction.
                    </p>
                  </div>
                </div>
              </div>
            </CardContent>
          </Card>

          <div className="flex justify-end gap-3">
            <Button type="button" variant="outline" onClick={() => router.back()}>
              Cancel
            </Button>
            <Button type="submit" isLoading={isLoading} disabled={!title.trim()}>
              Create & Open Editor
            </Button>
          </div>
        </form>
      </div>
    </DashboardLayout>
  );
}

'use client';

