import {
  Sparkles,
  Save,
  Eye,
  Plus,
  Trash2,
  CheckCircle2,
  ArrowLeft,
  Layout,
  AlignLeft,
  Loader2
} from 'lucide-react';
import { cn } from '@/lib/utils';

export default function ResumeEditPage() {
  const params = useParams();
  const router = useRouter();
  const id = params?.id as string;

  const [resume, setResume] = useState<IResume | null>(null);
  const [loading, setLoading] = useState(true);
  const [isSaving, setIsSaving] = useState(false);
  const [saveToast, setSaveToast] = useState(false);
  const [isGenerating, setIsGenerating] = useState<string | null>(null);

  // New item inputs
  const [newSkill, setNewSkill] = useState('');
  const [newAchievement, setNewAchievement] = useState('');

  useEffect(() => {
    if (id) {
      loadResume(id);
    }
  }, [id]);

  const loadResume = async (resumeId: string) => {
    try {
      const res = await api.getResume(resumeId);
      if (res?.data?.resume) {
        setResume(res.data.resume);
      }
    } catch (err) {
      console.error('Failed to load resume:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSave = async () => {
    if (!resume) return;
    setIsSaving(true);
    try {
      const res = await api.updateResume(resume._id, resume);
      if (res?.data?.resume) {
        setResume(res.data.resume);
      }
      setSaveToast(true);
      setTimeout(() => setSaveToast(false), 3000);
    } catch (err) {
      console.error('Failed to save resume:', err);
    } finally {
      setIsSaving(false);
    }
  };

  const handleAIGenerate = async (section: 'summary' | 'experience' | 'skills' | 'achievements', prompt: string) => {
    if (!resume) return;
    setIsGenerating(section);
    try {
      const res = await api.generateResumeSection(resume._id, section, prompt);
      if (res?.data?.resume) {
        setResume(res.data.resume);
      }
    } catch (err) {
      console.error(`Failed to generate ${section}:`, err);
    } finally {
      setIsGenerating(null);
    }
  };

  if (loading || !resume) {
    return (
      <DashboardLayout>
        <div className="h-96 flex items-center justify-center text-slate-400">
          <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <div className="space-y-6">
        {/* Top Control Bar */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-slate-200">
          <div className="flex items-center gap-3">
            <Link href="/resumes">
              <Button size="sm" variant="outline" className="p-2">
                <ArrowLeft className="w-4 h-4" />
              </Button>
            </Link>
            <div>
              <input
                type="text"
                value={resume.title}
                onChange={(e) => setResume({ ...resume, title: e.target.value })}
                className="text-xl font-bold text-slate-900 bg-transparent border-b border-transparent hover:border-slate-300 focus:border-blue-600 focus:outline-none transition-colors px-1"
              />
              <p className="text-xs text-slate-400 px-1">All changes are saved to your account</p>
            </div>
          </div>

          <div className="flex items-center gap-3">
            {/* Template Selector */}
            <div className="flex items-center bg-slate-100 p-1 rounded-lg border border-slate-200">
              <button
                type="button"
