                ))}
              </CardContent>
            </Card>
          </div>

          {/* Right Live Preview Column */}
          <div className="lg:col-span-5">
            <div className="sticky top-24 space-y-3">
              <div className="flex items-center justify-between px-1">
                <span className="text-xs font-bold uppercase tracking-wider text-slate-500">
                  Live Preview ({resume.template === 'ATS_CLASSIC' ? 'ATS Classic' : 'Modern Professional'})
                </span>
                <Link href={`/resumes/${resume._id}/preview`} className="text-xs text-blue-600 hover:underline">
                  Full View
                </Link>
              </div>

              <div className="rounded-xl border border-slate-300 bg-slate-100 p-3 max-h-[calc(100vh-10rem)] overflow-y-auto shadow-inner">
                <div className="scale-[0.85] origin-top">
                  <ResumePreview resume={resume} />
                </div>
              </div>
            </div>
          </div>
        </div>
      </div>
    </DashboardLayout>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { useParams, useRouter } from 'next/navigation';
import Link from 'next/link';
import { DashboardLayout } from '@/components/layout/DashboardLayout';
import { api } from '@/lib/api';
import { IResume, ResumeTemplateType } from '@/types';
import { ResumePreview } from '@/components/templates/ResumePreview';
import { Button } from '@/components/ui/Button';
import {
  Printer,
  Download,
  Edit,
  ArrowLeft,
  Layout,
  AlignLeft,
  Loader2
} from 'lucide-react';
import { cn } from '@/lib/utils';

export default function ResumePreviewPage() {
  const params = useParams();
  const router = useRouter();
  const id = params?.id as string;

  const [resume, setResume] = useState<IResume | null>(null);
  const [selectedTemplate, setSelectedTemplate] = useState<ResumeTemplateType>('MODERN_PROFESSIONAL');
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    if (id) {
      api.getResume(id)
        .then((res) => {
          if (res?.data?.resume) {
            setResume(res.data.resume);
            setSelectedTemplate(res.data.resume.template || 'MODERN_PROFESSIONAL');
          }
        })
        .catch((err) => console.error(err))
        .finally(() => setLoading(false));
    }
  }, [id]);

  const handlePrint = () => {
    window.print();
  };

  const handleDownloadHtml = async () => {
    if (!resume) return;
    try {
      const res = await api.exportResume(resume._id, selectedTemplate);
      if (res?.data?.html) {
        const blob = new Blob([res.data.html], { type: 'text/html' });
        const url = URL.createObjectURL(blob);
        const a = document.createElement('a');
        a.href = url;
        a.download = `${resume.title.replace(/\s+/g, '_')}_${selectedTemplate}.html`;
        a.click();
        URL.revokeObjectURL(url);
      }
    } catch (err) {
      console.error('Failed to download resume:', err);
    }
  };

  if (loading || !resume) {
    return (
      <DashboardLayout>
        <div className="h-96 flex items-center justify-center text-slate-400">
          <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <div className="space-y-6">
        {/* Print / Export Control Bar */}
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 pb-4 border-b border-slate-200 print:hidden">
          <div className="flex items-center gap-3">
            <Link href={`/resumes/${resume._id}/edit`}>
              <Button size="sm" variant="outline" className="gap-1.5">
                <ArrowLeft className="w-4 h-4" /> Back to Editor
              </Button>
            </Link>
            <h1 className="text-xl font-bold text-slate-900">{resume.title}</h1>
          </div>

          <div className="flex items-center gap-3">
            {/* Live Template Toggle */}
            <div className="flex items-center bg-slate-100 p-1 rounded-lg border border-slate-200">
              <button
                type="button"
                onClick={() => setSelectedTemplate('MODERN_PROFESSIONAL')}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-semibold transition-colors',
                  selectedTemplate === 'MODERN_PROFESSIONAL'
                    ? 'bg-white text-blue-700 shadow-sm'
                    : 'text-slate-600 hover:text-slate-900'
                )}
              >
                <Layout className="w-3.5 h-3.5" /> Modern
              </button>
              <button
                type="button"
                onClick={() => setSelectedTemplate('ATS_CLASSIC')}
                className={cn(
                  'flex items-center gap-1.5 px-3 py-1.5 rounded-md text-xs font-semibold transition-colors',
                  selectedTemplate === 'ATS_CLASSIC'
                    ? 'bg-white text-blue-700 shadow-sm'
                    : 'text-slate-600 hover:text-slate-900'
                )}
              >
                <AlignLeft className="w-3.5 h-3.5" /> ATS Classic
              </button>
            </div>

            <Button size="sm" variant="outline" onClick={handleDownloadHtml} className="gap-1.5">
              <Download className="w-4 h-4" /> Export HTML
            </Button>

            <Button size="sm" onClick={handlePrint} className="gap-1.5">
              <Printer className="w-4 h-4" /> Print / Save PDF
            </Button>
          </div>
        </div>

        {/* Rendered Document */}
        <div className="p-4 sm:p-8 bg-slate-100 rounded-2xl border border-slate-200 shadow-inner flex justify-center">
          <ResumePreview resume={resume} templateOverride={selectedTemplate} />
        </div>
      </div>
    </DashboardLayout>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import Link from 'next/link';
import { DashboardLayout } from '@/components/layout/DashboardLayout';
import { api } from '@/lib/api';
import { IBooking, BookingStatus } from '@/types';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import { Input } from '@/components/ui/Input';
import { formatCurrency } from '@/lib/utils';
import {
  CalendarCheck2,
  Plus,
  Search,
  Video,
  Clock,
  XCircle,
  ExternalLink,
  ChevronLeft,
  ChevronRight,
  Loader2
} from 'lucide-react';

export default function ConsultationsListPage() {
  const [bookings, setBookings] = useState<IBooking[]>([]);
  const [loading, setLoading] = useState(true);
  const [page, setPage] = useState(1);
  const [totalPages, setTotalPages] = useState(1);
  const [total, setTotal] = useState(0);
  const [search, setSearch] = useState('');
  const [statusFilter, setStatusFilter] = useState<string>('');

  useEffect(() => {
    loadBookings();
  }, [page, statusFilter]);

  const loadBookings = async () => {
    setLoading(true);
    try {
      const res = await api.getBookings(page, 5, statusFilter || undefined, search || undefined);
      if (res?.data) {
        setBookings(res.data);
        if (res.pagination) {
          setTotalPages(res.pagination.totalPages || 1);
          setTotal(res.pagination.total || 0);
        }
      }
    } catch (err) {
      console.error('Failed to load bookings:', err);
    } finally {
      setLoading(false);
    }
  };

  const handleSearchSubmit = (e: React.FormEvent) => {
    e.preventDefault();
    setPage(1);
    loadBookings();
  };

  const handleCancel = async (id: string) => {
    if (!confirm('Are you sure you want to cancel this consultation booking?')) return;
    try {
      await api.cancelBooking(id);
      loadBookings();
    } catch (err) {
      console.error('Failed to cancel booking:', err);
    }
  };

  const handlePayNow = async (bookingId: string) => {
    try {
      const res = await api.createCheckoutSession(bookingId);
      if (res?.data?.checkoutUrl) {
        window.location.href = res.data.checkoutUrl;
      }
    } catch (err) {
      console.error('Failed to start checkout:', err);
    }
  };

  return (
    <DashboardLayout>
      <div className="space-y-6">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4">
          <div>
            <h1 className="text-2xl font-bold tracking-tight text-slate-900">My Consultations</h1>
            <p className="text-sm text-slate-500 mt-1">
              Track your scheduled appointments, join video links, and manage upcoming career sessions.
            </p>
          </div>
          <Link href="/consultations/book">
            <Button className="gap-2">
              <Plus className="w-4 h-4" /> Book New Consultation
            </Button>
          </Link>
        </div>

        {/* Filters & Search Bar */}
        <div className="flex flex-col sm:flex-row gap-3 items-center justify-between bg-white p-4 rounded-xl border border-slate-200">
          <form onSubmit={handleSearchSubmit} className="flex gap-2 w-full sm:w-80">
            <Input
              value={search}
              onChange={(e) => setSearch(e.target.value)}
              placeholder="Search by agenda, name, email..."
              className="h-9 text-xs"
            />
            <Button type="submit" size="sm" variant="secondary" className="h-9 px-3">
              <Search className="w-3.5 h-3.5" />
            </Button>
          </form>

          {/* Status Filter */}
          <div className="flex items-center gap-2 w-full sm:w-auto overflow-x-auto pb-1 sm:pb-0">
            <span className="text-xs font-semibold text-slate-500 whitespace-nowrap">Filter Status:</span>
            {['', 'PENDING_PAYMENT', 'CONFIRMED', 'CANCELLED', 'COMPLETED'].map((st) => (
              <button
                key={st}
                onClick={() => {
                  setStatusFilter(st);
                  setPage(1);
                }}
                className={`px-2.5 py-1 rounded-lg text-xs font-medium whitespace-nowrap transition-colors ${
                  statusFilter === st
                    ? 'bg-blue-600 text-white font-semibold'
                    : 'bg-slate-100 text-slate-600 hover:bg-slate-200'
                }`}
              >
                {st === '' ? 'All' : st}
              </button>
            ))}
          </div>
        </div>

        {/* Bookings Table / List */}
        {loading ? (
          <div className="h-64 flex items-center justify-center text-slate-400">
            <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
          </div>
        ) : bookings.length === 0 ? (
          <Card className="py-16 text-center">
            <CalendarCheck2 className="w-12 h-12 text-slate-300 mx-auto mb-3" />
            <h3 className="text-base font-semibold text-slate-900">No consultations found</h3>
            <p className="text-xs text-slate-500 mt-1 max-w-sm mx-auto mb-4">
              You haven&apos;t booked any sessions matching your filter criteria.
            </p>
            <Link href="/consultations/book">
              <Button size="sm">Browse Career Experts</Button>
            </Link>
          </Card>
        ) : (
          <div className="space-y-4">
            {bookings.map((booking) => {
              const startDate = new Date(booking.startTime);
              const isConfirmed = booking.status === 'CONFIRMED';
              const isPending = booking.status === 'PENDING_PAYMENT';
              const isCancelled = booking.status === 'CANCELLED';

              return (
                <Card key={booking._id} className="hover:border-slate-300 transition-all">
                  <CardContent className="p-5 flex flex-col md:flex-row items-start md:items-center justify-between gap-4">
                    <div className="space-y-1.5 flex-1 min-w-0">
                      <div className="flex flex-wrap items-center gap-2">
                        <span className="font-bold text-slate-900 text-base">
                          {booking.consultantId?.name || 'Expert Consultant'}
                        </span>
                        <Badge
                          variant={
                            isConfirmed ? 'success' : isPending ? 'warning' : isCancelled ? 'danger' : 'neutral'
                          }
                        >
                          {booking.status}
                        </Badge>
                        <span className="text-xs font-semibold text-slate-500">
                          {formatCurrency(booking.amount, booking.currency)}
                        </span>
                      </div>

                      <p className="text-xs text-slate-600 font-medium">
                        Agenda: <span className="font-normal">{booking.agenda}</span>
                      </p>

                      <div className="flex flex-wrap items-center gap-4 text-xs text-slate-400 pt-1">
                        <span className="flex items-center gap-1">
                          <Clock className="w-3.5 h-3.5 text-slate-500" />
                          {startDate.toLocaleDateString('en-US', {
                            weekday: 'short',
                            month: 'short',
                            day: 'numeric',
                            year: 'numeric',
                          })}{' '}
                          at{' '}
                          {startDate.toLocaleTimeString('en-US', {
                            hour: '2-digit',
                            minute: '2-digit',
                          })}
                        </span>
                        <span>Duration: {booking.durationMinutes || 45} mins</span>
                      </div>
                    </div>

                    <div className="flex items-center gap-2 self-end md:self-center">
                      {isPending && (
                        <Button
                          size="sm"
                          onClick={() => handlePayNow(booking._id)}
                          className="gap-1.5 bg-emerald-600 hover:bg-emerald-700 text-white"
                        >
                          Pay with Stripe
                        </Button>
                      )}

                      {isConfirmed && booking.meetingUrl && (
                        <a
                          href={booking.meetingUrl}
                          target="_blank"
                          rel="noreferrer"
                          className="inline-flex items-center gap-1.5 px-3 py-1.5 rounded-lg bg-blue-50 text-blue-700 hover:bg-blue-100 text-xs font-semibold transition-colors"
                        >
                          <Video className="w-3.5 h-3.5 text-blue-600" /> Join Meeting
                        </a>
                      )}

                      {!isCancelled && booking.status !== 'COMPLETED' && (
                        <Button
                          size="sm"
                          variant="ghost"
                          onClick={() => handleCancel(booking._id)}
                          className="text-xs text-red-600 hover:bg-red-50"
                        >
                          Cancel
                        </Button>
                      )}
                    </div>
                  </CardContent>
                </Card>
              );
            })}

            {/* Pagination Controls */}
            <div className="flex items-center justify-between pt-4 border-t border-slate-200 text-xs text-slate-500">
              <span>
                Showing page {page} of {totalPages} ({total} total bookings)
              </span>
              <div className="flex items-center gap-2">
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setPage((p) => Math.max(1, p - 1))}
                  disabled={page <= 1}
                  className="h-8 px-2.5"
                >
                  <ChevronLeft className="w-4 h-4" />
                </Button>
                <Button
                  size="sm"
                  variant="outline"
                  onClick={() => setPage((p) => Math.min(totalPages, p + 1))}
                  disabled={page >= totalPages}
                  className="h-8 px-2.5"
                >
                  <ChevronRight className="w-4 h-4" />
                </Button>
              </div>
            </div>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { useRouter } from 'next/navigation';
import { DashboardLayout } from '@/components/layout/DashboardLayout';
import { api } from '@/lib/api';
import { IConsultant, IUser } from '@/types';
import { Card, CardHeader, CardTitle, CardDescription, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Input } from '@/components/ui/Input';
import { Badge } from '@/components/ui/Badge';
import { formatCurrency } from '@/lib/utils';
import {
  Calendar,
  Clock,
  User,
  Mail,
  Phone,
  CheckCircle,
  Briefcase,
  AlertCircle,
  Loader2,
  ArrowRight
} from 'lucide-react';
import { cn } from '@/lib/utils';

export default function BookConsultationPage() {
  const router = useRouter();

  const [consultants, setConsultants] = useState<IConsultant[]>([]);
  const [selectedConsultant, setSelectedConsultant] = useState<IConsultant | null>(null);
  const [selectedDate, setSelectedDate] = useState<string>('');
  const [availableSlots, setAvailableSlots] = useState<Array<{ startTime: string; endTime: string; isAvailable: boolean }>>([]);
  const [selectedSlot, setSelectedSlot] = useState<string | null>(null);

  // Booking details
  const [userName, setUserName] = useState('');
  const [userEmail, setUserEmail] = useState('');
  const [userPhone, setUserPhone] = useState('');
  const [agenda, setAgenda] = useState('');

  const [loadingConsultants, setLoadingConsultants] = useState(true);
  const [loadingSlots, setLoadingSlots] = useState(false);
  const [isSubmitting, setIsSubmitting] = useState(false);
  const [error, setError] = useState<string | null>(null);

  // Initialize date to tomorrow (YYYY-MM-DD)
  useEffect(() => {
    const tomorrow = new Date();
    tomorrow.setDate(tomorrow.getDate() + 1);
    setSelectedDate(tomorrow.toISOString().split('T')[0]);

    // Load current user profile for prefilling
    api.getMe()
      .then((res) => {
        if (res?.data?.user) {
          const u: IUser = res.data.user;
          setUserName(u.name || '');
          setUserEmail(u.email || '');
          setPhoneIfAny(u.profile?.phone);
        }
      })
      .catch(() => {});

    // Load active consultants
    api.getConsultants()
      .then((res) => {
        if (res?.data?.consultants) {
          setConsultants(res.data.consultants);
          if (res.data.consultants.length > 0) {
            setSelectedConsultant(res.data.consultants[0]);
          }
        }
      })
      .catch((err) => console.error('Failed to load consultants:', err))
      .finally(() => setLoadingConsultants(false));
  }, []);

  const setPhoneIfAny = (p?: string) => {
    if (p) setUserPhone(p);
  };

  // Fetch availability when consultant or date changes
  useEffect(() => {
    if (selectedConsultant && selectedDate) {
      setLoadingSlots(true);
      setSelectedSlot(null);
      api.getConsultantAvailability(selectedConsultant._id, selectedDate)
        .then((res) => {
          if (res?.data?.slots) {
            setAvailableSlots(res.data.slots);
          }
        })
        .catch((err) => console.error('Failed to load availability:', err))
        .finally(() => setLoadingSlots(false));
    }
  }, [selectedConsultant, selectedDate]);

  const handleBookAndPay = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!selectedConsultant || !selectedSlot) return;

    setError(null);
    setIsSubmitting(true);

    try {
      // 1. Create booking in PENDING_PAYMENT
      const bookingRes = await api.createBooking({
        consultantId: selectedConsultant._id,
        startTime: selectedSlot,
        userName,
        userEmail,
        userPhone,
        agenda,
      });

      const bookingId = bookingRes?.data?.booking?._id;
      if (!bookingId) {
        throw new Error('Failed to create booking reservation');
      }

      // 2. Create Stripe Checkout Session
      const checkoutRes = await api.createCheckoutSession(bookingId);
      const checkoutUrl = checkoutRes?.data?.checkoutUrl;

      if (checkoutUrl) {
        window.location.href = checkoutUrl;
      } else {
        router.push(`/consultations`);
      }
    } catch (err: any) {
      setError(err.message || 'Booking reservation failed. Please try another time.');
      setIsSubmitting(false);
    }
  };

  return (
    <DashboardLayout>
      <div className="max-w-4xl mx-auto space-y-8">
        <div>
          <h1 className="text-2xl font-bold tracking-tight text-slate-900">Book an Expert Consultation</h1>
          <p className="text-sm text-slate-500 mt-1">
            Connect 1-on-1 with Staff/Principal industry leaders for mock interviews, career roadmapping, and offer negotiation.
          </p>
        </div>

        {error && (
          <div className="p-4 rounded-xl bg-red-50 border border-red-200 text-red-700 text-sm flex items-center gap-2">
            <AlertCircle className="w-5 h-5 flex-shrink-0" />
            <span>{error}</span>
          </div>
        )}

        <form onSubmit={handleBookAndPay} className="space-y-8">
          {/* Step 1: Select Consultant */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base flex items-center gap-2">
                <span className="w-6 h-6 rounded-full bg-blue-600 text-white text-xs flex items-center justify-center font-bold">1</span>
                Select a Career Expert
              </CardTitle>
              <CardDescription>Choose from our vetted roster of industry veterans</CardDescription>
            </CardHeader>
            <CardContent>
              {loadingConsultants ? (
                <div className="h-28 flex items-center justify-center text-slate-400">
                  <Loader2 className="w-6 h-6 animate-spin text-blue-600" />
                </div>
              ) : (
                <div className="grid grid-cols-1 md:grid-cols-3 gap-4">
                  {consultants.map((c) => {
                    const isSelected = selectedConsultant?._id === c._id;
                    return (
                      <div
                        key={c._id}
                        onClick={() => setSelectedConsultant(c)}
                        className={cn(
                          'p-5 rounded-xl border-2 cursor-pointer transition-all flex flex-col justify-between',
                          isSelected
                            ? 'border-blue-600 bg-blue-50/40 shadow-sm'
                            : 'border-slate-200 hover:border-slate-300 bg-white'
                        )}
                      >
                        <div>
                          <div className="flex items-center justify-between mb-3">
                            <span className="font-bold text-slate-900 text-base">{c.name}</span>
                            <span className="text-xs font-bold text-blue-600">
                              {formatCurrency(c.hourlyRate)}
                            </span>
                          </div>
                          <p className="text-xs text-slate-500 line-clamp-2 mb-3">{c.title}</p>
                          <div className="flex flex-wrap gap-1">
                            {c.expertise.slice(0, 3).map((exp, idx) => (
                              <span key={idx} className="px-2 py-0.5 rounded bg-slate-100 text-[10px] text-slate-600 font-medium">
                                {exp}
                              </span>
                            ))}
                          </div>
                        </div>

                        <div className="mt-4 pt-3 border-t border-slate-100 flex items-center justify-between text-xs text-slate-400">
                          <span>{c.durationMinutes} min session</span>
                          {isSelected && <span className="font-bold text-blue-600">Selected</span>}
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </CardContent>
          </Card>

          {/* Step 2: Choose Date & Time Slot */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base flex items-center gap-2">
                <span className="w-6 h-6 rounded-full bg-blue-600 text-white text-xs flex items-center justify-center font-bold">2</span>
                Choose Date & Available Slot
              </CardTitle>
              <CardDescription>Real-time slot availability for {selectedConsultant?.name}</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="max-w-xs">
                <Input
                  label="Select Consultation Date"
                  type="date"
                  value={selectedDate}
                  min={new Date().toISOString().split('T')[0]}
                  onChange={(e) => setSelectedDate(e.target.value)}
                />
              </div>

              <div>
                <label className="block text-xs font-semibold text-slate-700 mb-2">Available Time Slots (UTC)</label>
                {loadingSlots ? (
                  <div className="p-6 text-center text-xs text-slate-400">Loading available times...</div>
                ) : availableSlots.length === 0 ? (
                  <p className="text-xs text-amber-600 bg-amber-50 p-3 rounded-lg border border-amber-200">
                    No open consultation slots available for this date. Please select another day.
                  </p>
                ) : (
                  <div className="grid grid-cols-2 sm:grid-cols-4 gap-2.5">
                    {availableSlots.map((slot) => {
                      const timeStr = new Date(slot.startTime).toLocaleTimeString([], {
                        hour: '2-digit',
                        minute: '2-digit',
                      });
                      const isSelected = selectedSlot === slot.startTime;

                      return (
                        <button
                          key={slot.startTime}
                          type="button"
                          disabled={!slot.isAvailable}
                          onClick={() => setSelectedSlot(slot.startTime)}
                          className={cn(
                            'p-3 rounded-xl border text-xs font-semibold transition-all flex items-center justify-center gap-2',
                            !slot.isAvailable && 'opacity-40 cursor-not-allowed bg-slate-50 border-slate-200 text-slate-400',
                            slot.isAvailable && !isSelected && 'border-slate-200 bg-white hover:border-blue-400 hover:bg-blue-50 text-slate-800',
                            isSelected && 'border-blue-600 bg-blue-600 text-white shadow-sm'
                          )}
                        >
                          <Clock className="w-3.5 h-3.5" />
                          {timeStr}
                        </button>
                      );
                    })}
                  </div>
                )}
              </div>
            </CardContent>
          </Card>

          {/* Step 3: Attendee Details & Agenda */}
          <Card>
            <CardHeader>
              <CardTitle className="text-base flex items-center gap-2">
                <span className="w-6 h-6 rounded-full bg-blue-600 text-white text-xs flex items-center justify-center font-bold">3</span>
                Session Agenda & Details
              </CardTitle>
              <CardDescription>Your information for the calendar invitation and video link</CardDescription>
            </CardHeader>
            <CardContent className="space-y-4">
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <Input
                  label="Your Name"
                  value={userName}
                  onChange={(e) => setUserName(e.target.value)}
                  placeholder="e.g. Alice Johnson"
                  required
                />
                <Input
                  label="Your Email"
                  type="email"
                  value={userEmail}
                  onChange={(e) => setUserEmail(e.target.value)}
                  placeholder="alice@example.com"
                  required
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                <Input
                  label="Phone Number (Optional)"
                  value={userPhone}
                  onChange={(e) => setUserPhone(e.target.value)}
                  placeholder="+1 (555) 0199"
                />
                <div className="flex flex-col justify-end">
                  <div className="p-3 bg-slate-50 border border-slate-200 rounded-lg text-xs text-slate-600">
                    Total Due: <strong className="text-slate-900 text-sm ml-1">{formatCurrency(selectedConsultant?.hourlyRate || 0)}</strong>
                  </div>
                </div>
              </div>

              <div>
                <label className="block text-sm font-medium text-slate-700 mb-1.5">Meeting Agenda & Goals</label>
                <textarea
                  rows={3}
                  value={agenda}
                  onChange={(e) => setAgenda(e.target.value)}
                  placeholder="Outline what you want to achieve (e.g. Meta L6 system design mock interview, compensation negotiation strategy for Staff offer...)"
                  className="w-full rounded-lg border border-slate-300 bg-white px-3 py-2 text-sm text-slate-900 placeholder:text-slate-400 focus:border-blue-500 focus:outline-none focus:ring-1 focus:ring-blue-500"
                  required
                />
              </div>
            </CardContent>
          </Card>

          <div className="flex justify-end pt-2">
            <Button
              type="submit"
              size="lg"
              isLoading={isSubmitting}
              disabled={!selectedSlot || !agenda.trim() || !userName.trim() || !userEmail.trim()}
              className="gap-2 shadow-lg shadow-blue-500/20"
            >
              Proceed to Stripe Checkout <ArrowRight className="w-5 h-5 ml-1" />
            </Button>
          </div>
        </form>
      </div>
    </DashboardLayout>
  );
}

'use client';

import React, { useEffect, useState } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { DashboardLayout } from '@/components/layout/DashboardLayout';
import { api } from '@/lib/api';
import { Card, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import {
  CheckCircle2,
  Calendar,
  Video,
  Mail,
  ArrowRight,
  Loader2,
  AlertCircle
} from 'lucide-react';
import { formatCurrency } from '@/lib/utils';

export default function PaymentSuccessPage() {
  const searchParams = useSearchParams();
  const sessionId = searchParams.get('session_id');
  const bookingId = searchParams.get('booking_id');

  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (sessionId || bookingId) {
      api.getPaymentStatus(bookingId || undefined, sessionId || undefined)
        .then((res) => {
          if (res?.data) {
            setData(res.data);
          }
        })
        .catch((err) => {
          console.error('Failed to verify payment status:', err);
          setError(err.message || 'Could not verify payment status from backend server.');
        })
        .finally(() => setLoading(false));
    } else {
      setLoading(false);
    }
  }, [sessionId, bookingId]);

  return (
    <DashboardLayout>
      <div className="max-w-xl mx-auto py-8">
        <Card className="text-center shadow-lg border-emerald-100">
          <CardContent className="p-8 space-y-6">
            {loading ? (
              <div className="py-12 space-y-3">
                <Loader2 className="w-10 h-10 animate-spin text-blue-600 mx-auto" />
                <p className="text-sm text-slate-500 font-medium">Verifying payment with backend database...</p>
              </div>
            ) : error ? (
              <div className="py-8 space-y-4">
                <div className="w-12 h-12 rounded-full bg-amber-50 text-amber-600 flex items-center justify-center mx-auto">
                  <AlertCircle className="w-7 h-7" />
                </div>
                <h2 className="text-xl font-bold text-slate-900">Payment Status Verification</h2>
                <p className="text-xs text-slate-500">{error}</p>
                <Link href="/consultations">
                  <Button variant="outline" className="mt-4">Go to My Consultations</Button>
                </Link>
              </div>
            ) : (
              <>
                <div className="w-16 h-16 rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center mx-auto">
                  <CheckCircle2 className="w-10 h-10" />
                </div>

                <div>
                  <h1 className="text-2xl font-extrabold text-slate-900">Payment Confirmed!</h1>
                  <p className="text-sm text-slate-500 mt-1">
                    Your career consultation booking has been verified and confirmed.
                  </p>
                </div>

                {data?.booking && (
                  <div className="bg-slate-50 rounded-xl p-5 border border-slate-200 text-left space-y-3 text-xs">
                    <div className="flex justify-between items-center pb-2 border-b border-slate-200">
                      <span className="font-semibold text-slate-700">Booking Status:</span>
                      <Badge variant="success">{data.booking.status}</Badge>
                    </div>

                    <div className="flex justify-between items-center">
                      <span className="text-slate-500">Consultant:</span>
                      <span className="font-semibold text-slate-900">{data.booking.consultantId?.name}</span>
                    </div>

                    <div className="flex justify-between items-center">
                      <span className="text-slate-500">Date & Time:</span>
                      <span className="font-semibold text-slate-900">
                        {new Date(data.booking.startTime).toLocaleString()}
                      </span>
                    </div>

                    <div className="flex justify-between items-center">
                      <span className="text-slate-500">Amount Paid:</span>
                      <span className="font-semibold text-slate-900">
                        {formatCurrency(data.amount, data.currency)}
                      </span>
                    </div>

                    {data.booking.meetingUrl && (
                      <div className="pt-2">
                        <a
                          href={data.booking.meetingUrl}
                          target="_blank"
                          rel="noreferrer"
                          className="flex items-center justify-center gap-2 p-2.5 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 transition-colors"
                        >
                          <Video className="w-4 h-4" /> Join Video Meeting
                        </a>
                      </div>
                    )}
                  </div>
                )}

                <div className="flex items-center justify-center gap-2 text-xs text-slate-400">
                  <Mail className="w-4 h-4" />
                  <span>A confirmation email with calendar details has been dispatched.</span>
                </div>

                <div className="pt-2">
                  <Link href="/consultations">
                    <Button size="lg" className="w-full gap-2">
                      View My Consultations <ArrowRight className="w-4 h-4" />
                    </Button>
                  </Link>
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </div>
    </DashboardLayout>
  );
}

