import React from 'react';
import Link from 'next/link';
import { DashboardLayout } from '@/components/layout/DashboardLayout';
import { Card, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { XCircle, ArrowLeft, CalendarCheck2 } from 'lucide-react';

export default function PaymentCancelPage() {
  return (
    <DashboardLayout>
      <div className="max-w-md mx-auto py-12">
        <Card className="text-center shadow-lg">
          <CardContent className="p-8 space-y-6">
            <div className="w-16 h-16 rounded-full bg-slate-100 text-slate-500 flex items-center justify-center mx-auto">
              <XCircle className="w-10 h-10 text-slate-400" />
            </div>

            <div>
              <h1 className="text-2xl font-bold text-slate-900">Payment Cancelled</h1>
              <p className="text-sm text-slate-500 mt-1">
                Your consultation booking was not confirmed. No charges were made to your account.
              </p>
            </div>

            <div className="pt-4 flex flex-col gap-2.5">
              <Link href="/consultations/book">
                <Button size="lg" className="w-full gap-2">
                  <CalendarCheck2 className="w-4 h-4" /> Try Booking Again
                </Button>
              </Link>
              <Link href="/consultations">
                <Button size="lg" variant="outline" className="w-full gap-2">
                  <ArrowLeft className="w-4 h-4" /> Back to Consultations
                </Button>
              </Link>
            </div>
          </CardContent>
        </Card>
      </div>
    </DashboardLayout>
  );
}

