'use client';

import React, { Suspense, useEffect, useState } from 'react';
import { useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { DashboardLayout } from '@/components/layout/DashboardLayout';
import { api } from '@/lib/api';
import { Card, CardContent } from '@/components/ui/Card';
import { Button } from '@/components/ui/Button';
import { Badge } from '@/components/ui/Badge';
import {
  CheckCircle2,
  Calendar,
  Video,
  Mail,
  ArrowRight,
  Loader2,
  AlertCircle
} from 'lucide-react';
import { formatCurrency } from '@/lib/utils';

function PaymentSuccessContent() {
  const searchParams = useSearchParams();
  const sessionId = searchParams.get('session_id');
  const bookingId = searchParams.get('booking_id');

  const [loading, setLoading] = useState(true);
  const [data, setData] = useState<any>(null);
  const [error, setError] = useState<string | null>(null);

  useEffect(() => {
    if (sessionId || bookingId) {
      api.getPaymentStatus(bookingId || undefined, sessionId || undefined)
        .then((res) => {
          if (res?.data) {
            setData(res.data);
          }
        })
        .catch((err) => {
          console.error('Failed to verify payment status:', err);
          setError(err.message || 'Could not verify payment status from backend server.');
        })
        .finally(() => setLoading(false));
    } else {
      setLoading(false);
    }
  }, [sessionId, bookingId]);

  return (
    <DashboardLayout>
      <div className="max-w-xl mx-auto py-8">
        <Card className="text-center shadow-lg border-emerald-100">
          <CardContent className="p-8 space-y-6">
            {loading ? (
              <div className="py-12 space-y-3">
                <Loader2 className="w-10 h-10 animate-spin text-blue-600 mx-auto" />
                <p className="text-sm text-slate-500 font-medium">Verifying payment with backend database...</p>
              </div>
            ) : error ? (
              <div className="py-8 space-y-4">
                <div className="w-12 h-12 rounded-full bg-amber-50 text-amber-600 flex items-center justify-center mx-auto">
                  <AlertCircle className="w-7 h-7" />
                </div>
                <h2 className="text-xl font-bold text-slate-900">Payment Status Verification</h2>
                <p className="text-xs text-slate-500">{error}</p>
                <Link href="/consultations">
                  <Button variant="outline" className="mt-4">Go to My Consultations</Button>
                </Link>
              </div>
            ) : (
              <>
                <div className="w-16 h-16 rounded-full bg-emerald-50 text-emerald-600 flex items-center justify-center mx-auto">
                  <CheckCircle2 className="w-10 h-10" />
                </div>

                <div>
                  <h1 className="text-2xl font-extrabold text-slate-900">Payment Confirmed!</h1>
                  <p className="text-sm text-slate-500 mt-1">
                    Your career consultation booking has been verified and confirmed.
                  </p>
                </div>

                {data?.booking && (
                  <div className="bg-slate-50 rounded-xl p-5 border border-slate-200 text-left space-y-3 text-xs">
                    <div className="flex justify-between items-center pb-2 border-b border-slate-200">
                      <span className="font-semibold text-slate-700">Booking Status:</span>
                      <Badge variant="success">{data.booking.status}</Badge>
                    </div>

                    <div className="flex justify-between items-center">
                      <span className="text-slate-500">Consultant:</span>
                      <span className="font-semibold text-slate-900">{data.booking.consultantId?.name}</span>
                    </div>

                    <div className="flex justify-between items-center">
                      <span className="text-slate-500">Date & Time:</span>
                      <span className="font-semibold text-slate-900">
                        {new Date(data.booking.startTime).toLocaleString()}
                      </span>
                    </div>

                    <div className="flex justify-between items-center">
                      <span className="text-slate-500">Amount Paid:</span>
                      <span className="font-semibold text-slate-900">
                        {formatCurrency(data.amount, data.currency)}
                      </span>
                    </div>

                    {data.booking.meetingUrl && (
                      <div className="pt-2">
                        <a
                          href={data.booking.meetingUrl}
                          target="_blank"
                          rel="noreferrer"
                          className="flex items-center justify-center gap-2 p-2.5 rounded-lg bg-blue-600 text-white font-bold hover:bg-blue-700 transition-colors"
                        >
                          <Video className="w-4 h-4" /> Join Video Meeting
                        </a>
                      </div>
                    )}
                  </div>
                )}

                <div className="flex items-center justify-center gap-2 text-xs text-slate-400">
                  <Mail className="w-4 h-4" />
                  <span>A confirmation email with calendar details has been dispatched.</span>
                </div>

                <div className="pt-2">
                  <Link href="/consultations">
                    <Button size="lg" className="w-full gap-2">
                      View My Consultations <ArrowRight className="w-4 h-4" />
                    </Button>
                  </Link>
                </div>
              </>
            )}
          </CardContent>
        </Card>
      </div>
    </DashboardLayout>
  );
}

export default function PaymentSuccessPage() {
  return (
    <Suspense
      fallback={
        <DashboardLayout>
          <div className="h-64 flex items-center justify-center">
            <Loader2 className="w-8 h-8 animate-spin text-blue-600" />
          </div>
        </DashboardLayout>
      }
    >
      <PaymentSuccessContent />
    </Suspense>
  );
}
